window.ScripturaLexicons.BDAG_PART_0103 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eikon-bdag\" data-source=\"BDAG\" data-search=\"εἰκών, όνος, ἡ eikṓn substantivo feminino imagem; retrato; imagem viva; forma; aparência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰκών, όνος, ἡ</td><td>substantivo feminino</td><td>imagem; retrato; imagem viva; forma; aparência</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heilamen-bdag\" data-source=\"BDAG\" data-search=\"εἱλάμην heilámēn forma verbal; remissão ver αἱρέομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἱλάμην</td><td>forma verbal; remissão</td><td>ver αἱρέομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eileutherosen-bdag\" data-source=\"BDAG\" data-search=\"εἰλευθέρωσεν eileuthérōsen forma verbal; remissão ver ἐλευθερόω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰλευθέρωσεν</td><td>forma verbal; remissão</td><td>ver ἐλευθερόω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eileo-bdag\" data-source=\"BDAG\" data-search=\"εἰλέω eiléō verbo envolver; enfaixar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰλέω</td><td>verbo</td><td>envolver; enfaixar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eilemma-eileptai-eilepha-bdag\" data-source=\"BDAG\" data-search=\"εἴλημμαι, εἴληπται, εἴληφα eílēmmai, eílēptai, eílēpha formas verbais; remissão ver λαμβάνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἴλημμαι, εἴληπται, εἴληφα</td><td>formas verbais; remissão</td><td>ver λαμβάνω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eilikrineia-bdag\" data-source=\"BDAG\" data-search=\"εἰλικρίνεια, ας, ἡ eilikríneia substantivo feminino sinceridade; pureza de intenção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰλικρίνεια, ας, ἡ</td><td>substantivo feminino</td><td>sinceridade; pureza de intenção</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eilikrines-bdag\" data-source=\"BDAG\" data-search=\"εἰλικρινής, ές, eilikrinḗs adjetivo de duas terminações puro; sincero; sem dissimulação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰλικρινής, ές,</td><td>adjetivo de duas terminações</td><td>puro; sincero; sem dissimulação</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eilikrinos-bdag\" data-source=\"BDAG\" data-search=\"εἰλικρινῶς eilikrinôs advérbio sinceramente; francamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰλικρινῶς</td><td>advérbio</td><td>sinceramente; francamente</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heilissō-bdag\" data-source=\"BDAG\" data-search=\"εἱλίσσω heilíssō verbo; remissão ver ἑλίσσω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἱλίσσω</td><td>verbo; remissão</td><td>ver ἑλίσσω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heilkon-heilkysa-bdag\" data-source=\"BDAG\" data-search=\"εἷλκον, εἵλκυσα heîlkon, heílkysa formas verbais; remissão ver ἕλκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἷλκον, εἵλκυσα</td><td>formas verbais; remissão</td><td>ver ἕλκω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heilkōmai-bdag\" data-source=\"BDAG\" data-search=\"εἵλκωμαι heílkōmai forma verbal; remissão ver ἑλκόομαι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἵλκωμαι</td><td>forma verbal; remissão</td><td>ver ἑλκόομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heilomen-bdag\" data-source=\"BDAG\" data-search=\"εἱλόμην heilómēn forma verbal; remissão ver αἱρέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἱλόμην</td><td>forma verbal; remissão</td><td>ver αἱρέω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eimi-bdag\" data-source=\"BDAG\" data-search=\"εἰμί eimí verbo copulativo, existencial e auxiliar ser; estar; existir; acontecer; pertencer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἰμί</td><td>verbo copulativo, existencial e auxiliar</td><td>ser; estar; existir; acontecer; pertencer</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eimi-go-bdag\" data-source=\"BDAG\" data-search=\"εἶμι eîmi verbo ir; irei BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἶμι</td><td>verbo</td><td>ir; irei</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heineken-bdag\" data-source=\"BDAG\" data-search=\"εἵνεκεν heíneken preposição com genitivo por causa de; em razão de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἵνεκεν</td><td>preposição com genitivo</td><td>por causa de; em razão de</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eixa-bdag\" data-source=\"BDAG\" data-search=\"εἶξα eîxa forma verbal; remissão ver εἴκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἶξα</td><td>forma verbal; remissão</td><td>ver εἴκω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eipa-eipein-bdag\" data-source=\"BDAG\" data-search=\"εἶπα, εἰπεῖν eîpa, eipeîn formas verbais; remissão ver εἶπον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἶπα, εἰπεῖν</td><td>formas verbais; remissão</td><td>ver εἶπον</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eiper-bdag\" data-source=\"BDAG\" data-search=\"εἴπερ eíper conjunção; remissão ver εἰ ⑥ⓛ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἴπερ</td><td>conjunção; remissão</td><td>ver εἰ ⑥ⓛ</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eipon-bdag\" data-source=\"BDAG\" data-search=\"εἶπον eîpon verbo; aoristo segundo de λέγω dizer; falar; responder; concluir; chamar; ordenar; pensar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἶπον</td><td>verbo; aoristo segundo de λέγω</td><td>dizer; falar; responder; concluir; chamar; ordenar; pensar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eipos-bdag\" data-source=\"BDAG\" data-search=\"εἴπως eípōs conjunção; remissão ver εἰ ⑥ⓝ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εἴπως</td><td>conjunção; remissão</td><td>ver εἰ ⑥ⓝ</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-eikon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰκών, όνος, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eikṓn⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Ésquilo, Heródoto e seguintes; palavra de empréstimo na literatura rabínica.)</p>\n<p><strong>① Objeto moldado para reproduzir a forma ou a aparência de alguma coisa; imagem, semelhança, retrato.</strong> (Cf. Dídimo, Gen. 82, 6.) Da cabeça do imperador numa moeda (assim Artemidoro 4, 31; sobre a imagem de um imperador, Josefo, Bell. 2, 169; 194, Ant. 19, 185; cf. AcThom 112 [Aa II/2, 223, 19]; D. Shotter, Gods, Emperors, and Coins, Greece and Rome, segunda série 26, 1979, 48–57), Mt 22:20; Mc 12:16; Lc 20:24. De uma imagem de deus (Diodoro Sículo 2, 8, 7 [Zeus]; Apiano, Mithrid. 117 §575: <span class=\"greek\">θεῶν εἰκόνες</span>, «imagens de deuses»; Luciano, Sacr. 11; 2Cr 33:7; Is 40:19; Justino, A I, 55, 7; Ath. 18, 1; veja T. Podella, Das Lichtkleid, 1996, sobretudo 83–88), Ap 13:14s.; 14:9, 11; 15:2; 16:2; 19:20; 20:4.</p>\n<p><strong>② Aquilo que tem a mesma forma de alguma outra coisa</strong>, mas não é um objeto fabricado como em ①: <strong>imagem viva</strong>; extensão figurada de ①. <span class=\"greek\">εἰκὼν τοῦ θεοῦ</span>, «imagem de Deus» (<span class=\"greek\">ἄνθρωπος πλάσμα καὶ εἰκὼν αὐτοῦ</span> [Deus], «o homem é criatura e imagem dele», Teófilo de Antioquia 1, 4 [p. 64, 17]; juntamente com <span class=\"greek\">ὁμοίωσις</span>, Dídimo, Gen. 56, 28), referente ao homem (cf. Mitt-Wilck. I/2, 109, 11 [século III a.C.]: Filopátor como <span class=\"greek\">εἰκὼν τοῦ Διός</span>; Pedra de Roseta = OGI 90, 3 [196 a.C.]: Ptolomeu V como <span class=\"greek\">εἰκὼν ζῶσα τοῦ Διός</span>, «imagem viva de Zeus»; cf. APF 1, 1901, 483, 11; Plutarco, Themist. 125 [27, 4]; Luciano, Pro Imag. 28: <span class=\"greek\">εἰκόνα θεοῦ τ</span>. <span class=\"greek\">ἄνθρωπον εἶναι</span>, «o homem é imagem de deus»; Diógenes Laércio 6, 51: <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγαθοὺς ἄνδρας θεῶν εἰκόνας εἶναι</span>, «os homens bons são imagens dos deuses»; Sextus 190; Herm. Wr. 1, 12 e outros; Apuleio como imagem de Deus: Reitzenstein, Mysterienreligionen³ 43; J. Hehn, Zum Terminus ‘Bild Gottes’, Festschrift E. Sachau, 1915, 36–52), 1Co 11:7 (sobre a gradação, cf. Herm. Wr. 11, 15a).</p>\n<p>Referente a Cristo (Hélio como <span class=\"greek\">εἰκών</span> da divindade: Platão, Rep. 509; Proclo, Hymni 1, 33s. [Orphica, p. 277 Abel]; Herm. Wr. 11, 15; Estobeu I 293, 21 = 454, 1ss. Sc.; Hiérocles 1, 418: os demais deuses são <span class=\"greek\">εἰκόνες</span> do deus primordial. — O Logos: Fílon, Conf. Ling. 97; 147. A Sabedoria: Sb 7:26), 2Co 4:4; Cl 1:15 (<span class=\"greek\">εἰ</span>. <span class=\"greek\">τοῦ θεοῦ ἐστιν ὁ υἱὸς αὐτοῦ ὁ μονογενής</span>, «o Filho unigênito de Deus é sua imagem», Dídimo, Gen. 58, 3; cf. <span class=\"greek\">εἰκὼν γὰρ τοῦ</span> … <span class=\"greek\">θεοῦ ὁ λόγος ἐστὶ αὐτοῦ</span>, «o Logos dele é imagem do Deus…», Orígenes, C. Cels. 4, 85, 24; E. Preuschen, ZNW 18, 1918, 243). <span class=\"greek\">εἰ</span>. <span class=\"greek\">τοῦ χοϊκοῦ</span>, <span class=\"greek\">τοῦ ἐπουρανίου</span>, «imagem do [homem] terreno, do celestial», 1Co 15:49 (veja S. McCasland, The Image of God According to Paul, JBL 69, 1950, 85–100). A imagem corresponde ao seu original (cf. <span class=\"greek\">ὁμοίωμα</span> 2ab; Doxopatres [século XI d.C.], Rhet. Gr. II 160, 1: <span class=\"greek\">εἰ</span>. <span class=\"greek\">καὶ ὁμοίωμα διαφέρει</span>; Melitão, P. 36, 245: <span class=\"greek\">διὰ τῆς τυπικῆς εἰκόνος</span>; 38, 262: <span class=\"greek\">τοῦ μέλλοντος ἐν αὐτῷ τὴν εἰκόνα βλέπεις</span>, e frequentemente na interpretação tipológica do Antigo Testamento).</p>\n<p><strong>③ Aquilo que representa outra coisa quanto à sua forma e às suas características essenciais; forma, aparência.</strong> (Ístro [século III a.C.], n.º 334, fragmento 53 Jac.: <span class=\"greek\">ἀνθρωποειδὴς εἰκών</span>, «figura humana»; Artemidoro 1, 35, p. 36, 5: <span class=\"greek\">τὸ πρόσωπον κ</span>. <span class=\"greek\">τὴν εἰκόνα</span>, «o rosto e a forma»; Pseudo-Calístenes 2, 27; Hiérocles 20, 465: para seus seguidores, Pitágoras tem <span class=\"greek\">θείαν εἰκόνα</span>, «aparência de um deus»; Cleópatra, linha 154: <span class=\"greek\">ἐτελειώθη ἡ εἰκὼν σώματι κ</span>. <span class=\"greek\">ψυχῇ κ</span>. <span class=\"greek\">πνεύματι</span>, «a imagem foi aperfeiçoada em corpo, alma e espírito»; Herm. Wr. 1, 12, acerca do primeiro homem, filho do <span class=\"greek\">πατὴρ πάντων</span>, «Pai de todos»: <span class=\"greek\">τὴν τοῦ πατρὸς εἰκόνα ἔχων</span>, «possuindo a imagem do Pai»; 5, 6; En 106:10.) <span class=\"greek\">ὁμοίωμα εἰκόνος φθαρτοῦ ἀνθρώπου</span>, «semelhança da forma de homem mortal», Rm 1:23 (M. Hooker, NTS 6, 1960, 297–306). <span class=\"greek\">συμμόρφους τῆς εἰ</span>. <span class=\"greek\">τοῦ υἱοῦ</span>, «conformes à aparência de seu Filho», Rm 8:29; cf. 2Co 3:18. <span class=\"greek\">εἰ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πραγμάτων</span>, «a forma das coisas», em oposição à <span class=\"greek\">σκιά</span>, «sombra», Hb 10:1.</p>\n<p>A influência de Gn 1:26s. é muito forte (<span class=\"greek\">κατ</span>’ <span class=\"greek\">εἰκόνα θεοῦ</span>, «conforme a imagem de Deus»; TestNapht 2:5; Taciano 12, 1 e outros; Justino, A I, 63, 16: <span class=\"greek\">εἰκόνος ἀσωμάτου</span>, «de uma imagem incorpórea». Veja A. Struker, Die Gottesebenbildlichkeit des Menschen in der christlichen Literatur der zwei ersten Jahrhunderte, 1913). Os seres humanos foram feitos por Deus <span class=\"greek\">ἐκ τῆς ἰδίας εἰ</span>., «à sua própria imagem», Dg 10:2; cf. <span class=\"greek\">τῆς ἑαυτοῦ εἰ</span>. <span class=\"greek\">χαρακτήρ</span>, «caráter [marca] da sua própria imagem», 1Cl 33:4; cf. versículo 5; B 5:5; 6:12. Gn 1:27 também influencia Cl 3:10: o novo homem é renovado <span class=\"greek\">κατ</span>’ <span class=\"greek\">εἰκόνα τοῦ κτίσαντος αὐτόν</span>, «segundo a imagem daquele que o criou». (Fílon, Leg. All. 3, 96, à maneira platônica, expressa o pensamento de que primeiramente emanou de Deus uma imagem que, por sua vez, serviu de modelo para os seres humanos; contra essa interpretação, veja F. Eltester, Eikon im NT, 1958, 157.)</p>\n<p>— E. Käsemann, Leib und Leib Christi: Beiträge zur Historischen Theologie 9, 1933, 81–88, 147–150; J. Bover, ‘Imaginis’ notio apud B. Paulum: Biblica 4, 1923, 174–179; H. Willms, <span class=\"greek\">Εἰκών</span> I, 1935; E. Selwyn, Image, Fact and Faith: NTS 1, 1955, 235–247; G. Ladner, RAC IV, 1959, 771–786 (bibliografia); J. Jervell, Imago Dei (Genesis, late Judaism, Gnosis, NT), FRLANT n.º 58, 1960; K. Prümm, Verbum Domini 40, 1962, 232–257 (Paulo); E. Larsson, Christus als Vorbild, 1962. — DELG, s.v. <span class=\"greek\">ἔοικα</span>. M-M. EDNT. TW. Spicq. Sv.</p></div></section></article> <article id=\"entry-heilamen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἱλάμην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heilámēn⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">αἱρέομαι</span>.</p></div></section></article> <article id=\"entry-eileutherosen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰλευθέρωσεν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eileuthérōsen⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">ἐλευθερόω</span>.</p></div></section></article> <article id=\"entry-eileo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰλέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eiléō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Futuro, segunda pessoa do singular, <span class=\"greek\">εἰλήσεις</span> (Jó 40:26, códice Vaticano A); primeiro aoristo <span class=\"greek\">εἴλησα</span> (4Rs 2:8); particípio perfeito passivo <span class=\"greek\">εἰλημένος</span> (LXX). (Hipócrates: CMG I/1, p. 97, 14; Licófron, versículo 1202: <span class=\"greek\">ἐν σπαργάνοις εἰλημένον</span>, «envolto em faixas», e outros; Hesíquio; TestSol.) <strong>Envolver, enfaixar</strong>, com dativo <span class=\"greek\">τινί</span>, «em alguma coisa» (cf. Is 11:5), GPt 6:24, conforme os manuscritos (veja <span class=\"greek\">ἐνειλέω</span>; a mesma variação em Herodiano 2, 1, 1, com variante de leitura). — DELG, s.v. <span class=\"greek\">εἰλέω</span> 1.</p></div></section></article> <article id=\"entry-eilemma-eileptai-eilepha-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴλημμαι, εἴληπται, εἴληφα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eílēmmai, eílēptai, eílēpha⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">λαμβάνω</span>.</p></div></section></article> <article id=\"entry-eilikrineia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰλικρίνεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eilikríneia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Também <span class=\"greek\">εἰλικρινία</span>; veja W-S. §5, 13c; Mlt-H. 100; 348. Desde Aristóteles e outros; POxy 1252 verso II, 38; PAberd 52, 8; Sb 7:25, variante de leitura; derivado de <span class=\"greek\">εἰλικρινής</span>.) <strong>Qualidade ou estado de quem está livre de dissimulação; sinceridade, pureza de intenção</strong>. Juntamente com <span class=\"greek\">ἀλήθεια</span>, «verdade», 1Co 5:8. <span class=\"greek\">ἐξ εἰλικρινείας</span>, «por motivos puros», 2Co 2:17; (com <span class=\"greek\">ἁπλότης</span>, «simplicidade», variante <span class=\"greek\">ἁγιότης</span>, «santidade») <span class=\"greek\">ἐν εἰ</span>. <span class=\"greek\">τοῦ θεοῦ</span>, «com sinceridade procedente de Deus», 2Co 1:12. — M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-eilikrines-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰλικρινής, ές,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eilikrinḗs⟧</span><span class=\"separator\">·</span><span>adjetivo de duas terminações</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Genitivo <span class=\"greek\">οῦς</span> (veja <span class=\"greek\">εἰλικρίνεια</span>; a etimologia «julgado à luz do sol» é duvidosa: veja Boisacq 223, nota 1; Chantraine, DELG 320; Hipócrates, Xenofonte, Platão e outros; Sb 7684, 3s.; Sb 7:25; Fílon; Josefo, Ant. 19, 321). Em geral, «sem mistura, sem liga»; daí, no sentido moral, <strong>sincero, sem motivos ocultos ou fingimento; puro</strong> (assim Platão, Phd. 66a: <span class=\"greek\">εἰλικρινεῖ τῇ διανοίᾳ χρώμενος</span>, «servindo-se de pensamento puro» [cf. Justino, D. 4, 1]; 81c: <span class=\"greek\">ψυχὴ εἰ</span>., «alma pura»; Élio Aristides 13, p. 158 D.; OGI 227, 12; 763, 40; TestBenj 6:5). «Sincero», juntamente com <span class=\"greek\">ἀπρόσκοπος</span>, «irrepreensível», Fp 1:10. Juntamente com <span class=\"greek\">ἀκέραιος</span>, «íntegro», 1Cl 2:5; <span class=\"greek\">εἰ</span>. <span class=\"greek\">διάνοια</span>, «mente pura» (veja Platão acima), 2Pe 3:1; <span class=\"greek\">καρδία</span>, «coração», 2Cl 9:8. — Frisk. M-M. TW. Spicq.</p></div></section></article> <article id=\"entry-eilikrinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰλικρινῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eilikrinôs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Advérbio de <span class=\"greek\">εἰλικρινής</span> (Platão; Epicteto 4, 2, 6; OGI 441, 5; Michel 394, 48; Fílon; Albino, Didasc. 11; Ath., R. 54, 28): <strong>sinceramente, francamente</strong>; <span class=\"greek\">κατανοεῖν</span>, «considerar», 1Cl 32:1.</p></div></section></article> <article id=\"entry-heilissō-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἱλίσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heilíssō⟧</span><span class=\"separator\">·</span><span>verbo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">ἑλίσσω</span>.</p></div></section></article> <article id=\"entry-heilkon-heilkysa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἷλκον, εἵλκυσα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heîlkon, heílkysa⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">ἕλκω</span>.</p></div></section></article> <article id=\"entry-heilkōmai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἵλκωμαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heílkōmai⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">ἑλκόομαι</span>.</p></div></section></article> <article id=\"entry-heilomen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἱλόμην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heilómēn⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">αἱρέω</span>.</p></div></section></article> <article id=\"entry-eimi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰμί</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eimí⟧</span><span class=\"separator\">·</span><span>verbo copulativo, existencial e auxiliar</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Homero e seguintes.) Imperativo <span class=\"greek\">ἴσθι</span>, <span class=\"greek\">ἔσο</span>, IPol 4:1, <span class=\"greek\">ἔστω</span> — também coloquial <span class=\"greek\">ἤτω</span> (BGU 276, 24; 419, 13; POxy 533, 9; Sl 103:31; 1Mac 10:31), 1Co 16:22; Tg 5:12; 1Cl 48:5; Hv 3, 3, 4; terceira pessoa do plural <span class=\"greek\">ἔστωσαν</span> (inscrições desde 200 a.C., Meisterhans³-Schw. 191; PPetr III, 2, 22 [237 a.C.]), Lc 12:35; 1Tm 3:12; GJs 7:2. Infinitivo <span class=\"greek\">εἶναι</span>. Imperfeito, primeira pessoa, somente médio <span class=\"greek\">ἤμην</span> (Josefo, Bell. 1, 389; 631; veja adiante); <span class=\"greek\">ἦν</span> apenas em At 20:18, códice D; segunda pessoa <span class=\"greek\">ἦσθα</span> (Josefo, Ant. 6, 104), Mt 26:69; Mc 14:67, e <span class=\"greek\">ἦς</span> (Lobeck, Phryn. 149: «diga-se <span class=\"greek\">ἦσθα</span>»; Josefo, Ant. 17, 110 e outros; Sb 6262, 16 [século III d.C.]), Mt 25:21, 23 e outros; terceira pessoa do singular <span class=\"greek\">ἦν</span>; primeira do plural <span class=\"greek\">ἦμεν</span>. Ao lado desta, a forma média <span class=\"greek\">ἤμην</span> (papiros desde o século III a.C.; Jó 29:16; Tb 12:13 BA), mencionada acima, produz o plural <span class=\"greek\">ἤμεθα</span> (papiros desde o século III a.C.; Br 1:19), Mt 23:30; At 27:37; Ef 2:3. Ambas as formas aparecem em sucessão em Gl 4:3. Futuro <span class=\"greek\">ἔσομαι</span>; particípio <span class=\"greek\">ἐσόμενος</span>. Os manuscritos divergem quanto à escolha da voz ativa ou média, mas, como as edições, inclinam-se para a média (W-S. §14, 1; Mlt-H. 201–203; Rob., índice; B-D-F §98; Rdm.² 99; 101s.; Helbing 108s.; Reinhold 86s.). Veja também <span class=\"greek\">ἔνι</span>.</p>\n<p><strong>① Ser, existir, estar presente, disponível.</strong> Emprego predicativo (para outros empregos predicativos, veja ③ⓐ, ④, ⑤, ⑥, ⑦). Referente a Deus (Epicuro em Diógenes Laércio 10, 123: <span class=\"greek\">θεοί εἰσιν</span>, «os deuses existem»; Zaleuco em Diodoro Sículo 12, 20, 2: <span class=\"greek\">θεοὺς εἶναι</span>, «existirem deuses»; Sb 12:13; Justino, D. 128, 4, acerca de anjos): <span class=\"greek\">ἔστιν ὁ θεός</span>, «Deus existe», Hb 11:6; cf. 1Co 8:5. <span class=\"greek\">ὁ ὢν καὶ ὁ ἦν</span>, «aquele que é e que era» (cf. SibOr 3, 16; como amuleto, PMich 155, 3 [século II d.C.]: <span class=\"greek\">ὁ ὢν θεὸς ὁ Ἰάω κύριος παντοκράτωρ</span>, «o deus… que existe, Iao, Senhor Todo-Poderoso»), Ap 11:17; 16:5. <span class=\"greek\">ὁ ὢν καὶ ὁ ἦν καὶ ὁ ἐρχόμενος</span>, «aquele que é, que era e que vem»; nesta e nas duas passagens anteriores, <span class=\"greek\">ἦν</span> é tratado como particípio (quanto ao uso incomum de <span class=\"greek\">ἦν</span>, cf. Simônides 74 D.: <span class=\"greek\">ἦν ἑκατὸν φιάλαι</span>, «eram cem taças»), Ap 1:4; 4:8 (cf. Êx 3:14; Sb 13:1; Pausânias 10, 12, 10: <span class=\"greek\">Ζεὺς ἦν</span>, <span class=\"greek\">Ζ</span>. <span class=\"greek\">ἔστι</span>, <span class=\"greek\">Ζ</span>. <span class=\"greek\">ἔσσεται</span>, «Zeus era, Zeus é, Zeus será»; cf. Theosophien 18; O. Weinreich, ARW 19, 1919, 178s.). <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">εἶναι θεὸν παντοκράτορα</span>, «nem existir Deus Todo-Poderoso», AcPlCor 1:11.</p>\n<p><span class=\"greek\">ἐγώ εἰμι</span>, «eu sou» (inscrição no templo de Atena-Ísis em Saís, segundo Plutarco, Is. et Os. 9, 354c: <span class=\"greek\">ἐγώ εἰμι πᾶν τὸ γεγονὸς κ</span>. <span class=\"greek\">ὸ̓ν κ</span>. <span class=\"greek\">ἐσόμενον</span>, «sou tudo o que veio a ser, o que é e o que virá a ser». Sobre o papel de Ísis na religião grega, veja I. Bergman, Ich bin Isis, 1968; R. Merkelbach, Isis Regina—Zeus Sarapis, 1995; bibliografia adicional em M. Gustafson, in Prayer from Alexander to Constantine, org. M. Kiley et al., 1997, 158), Ap 1:8 (veja o início de <span class=\"greek\">ἐγώ</span>). <span class=\"greek\">ὁ ὤν</span>, … <span class=\"greek\">θεός</span>, Rm 9:5, é classificado aqui e entendido como referente a Cristo por J. Wordsworth, ad loc., e H. Warner, JTS 48, 1947, 203s.</p>\n<p>Referente ao <span class=\"greek\">λόγος</span>: <span class=\"greek\">ἐν ἀρχῇ ἦν ὁ λ</span>., «no princípio era o Logos», Jo 1:1 (para <span class=\"greek\">ἦν</span>, cf. Herm. Wr. 1, 4; 3, 1b: <span class=\"greek\">ἦν σκότος</span>, «havia trevas»; fragmento IX 1, p. 422, 23 Sc.: <span class=\"greek\">γέγονεν ἡ ὕλη καὶ ἦν</span>, «a matéria surgiu e existia»). — Referente a Cristo: <span class=\"greek\">πρὶν Ἀβραὰμ γενέσθαι</span>, <span class=\"greek\">ἐγὼ εἰμί</span>, «antes que Abraão nascesse, eu sou», Jo 8:58 (sobre o presente <span class=\"greek\">εἰμί</span>, cf. Parmênides 8, 5: do Eterno não podemos dizer <span class=\"greek\">ἦν οὐδ</span>’ <span class=\"greek\">ἔσται</span>, «era nem será», mas somente <span class=\"greek\">ἔστιν</span>, «é»; Amônio, filho de Hérmias [Comm. in Aristotl. IV 5, ed. A. Busse, 1897], 6, p. 172: no Timeu lemos que não se deve dizer dos deuses <span class=\"greek\">τὸ ἦν ἢ τὸ ἔσται μεταβολῆς τινος ὄντα σημαντικά</span>, «era» ou «será», porque sugerem alguma mudança, mas apenas <span class=\"greek\">ἔστι</span>, «é»; Sl 89:2; D. Ball, ‘I Am’ in John’s Gospel [JSNT Suppl. 124], 1996). — Referente ao mundo: <span class=\"greek\">πρὸ τοῦ τὸν κόσμον εἶναι</span>, «antes de o mundo existir», Jo 17:5. Satiricamente, acerca da besta que parodia o Cordeiro, <span class=\"greek\">ἦν καὶ οὐκ ἔστιν</span>, «era e já não é», Ap 17:8. Referente ao templo de Deus: <span class=\"greek\">ἔστιν</span>, «existe», B 16:6s.</p>\n<p><span class=\"greek\">τὸ μὴ ὄν</span>, «aquilo que não existe, o irreal» (Salústio 17, p. 32, 7 e 9; Fílon, Aet. M. 5; 82), Hm 1:1. <span class=\"greek\">τὰ ὄντα</span>, «o que existe», contraposto a <span class=\"greek\">τὰ μὴ ὄντα</span>, «o que não existe», Rm 4:17; cf. 1Co 1:28; 2Cl 1:8. Referente a Deus: <span class=\"greek\">κτίσας ἐκ τοῦ μὴ ὄντος τὰ ὄντα</span>, «que criou o que existe a partir do que não existe», Hv 1, 1, 6 (sobre o contraste <span class=\"greek\">τὰ ὄντα</span> e <span class=\"greek\">τὰ μὴ ὄντα</span>, cf. Pseudo-Aristóteles sobre Xenófanes, fragmento 21, 28; Artemidoro 1, 51, p. 49, 19: <span class=\"greek\">τὰ μὴ ὄντα ὡς ὄντα</span>, «coisas inexistentes como se existentes»; Ocelo Lucano 12; Salústio 17, 5, p. 30, 28–32, 12; Fílon, Op. M. 81; PGM 4, 3077s.: <span class=\"greek\">ποιήσαντα τὰ πάντα ἐξ ὧν οὐκ ὄντων εἰς τὸ εἶναι</span>; 13, 272s.: <span class=\"greek\">τὸν ἐκ μὴ ὄντων εἶναι ποιήσαντα καὶ ἐξ ὄντων μὴ εἶναι</span>; Teófilo de Antioquia 1, 4 [p. 64, 21]: <span class=\"greek\">τὰ πάντα ὁ θεὸς ἐποίησεν ἐξ οὐκ ὄντων εἰς τὸ εἶναι</span>, «Deus fez todas as coisas, do não ser para o ser»).</p>\n<p>De existir no sentido de <strong>estar presente, disponível, provido</strong>: <span class=\"greek\">πολλοῦ ὄχλου ὄντος</span>, «visto que havia uma grande multidão presente», Mc 8:1; <span class=\"greek\">ὄντων τῶν προσφερόντων</span>, «havendo quem apresentasse ofertas», Hb 8:4; <span class=\"greek\">οὔπω ἦν πνεῦμα</span>, «o Espírito ainda não havia vindo», Jo 7:39; <span class=\"greek\">ἀκούσας ὄντα σιτία</span>, «ouvindo que havia trigo disponível», At 7:12.</p>\n<p>Frequentemente serve para introduzir parábolas e histórias: <strong>havia [certa vez]</strong>: <span class=\"greek\">ἄνθρωπός τις ἦν πλούσιος</span>, «havia [certa vez] um homem rico», Lc 16:1, 19; <span class=\"greek\">ἦν ἄνθρωπος ἐκ τ</span>. <span class=\"greek\">Φαρισαίων</span>, «havia entre os fariseus um homem», Jo 3:1. «Há, existem»: <span class=\"greek\">ὥσπερ εἰσὶν θεοὶ πολλοί</span>, «assim como há muitos deuses», 1Co 8:5; <span class=\"greek\">διαιρέσεις χαρισμάτων εἰσίν</span>, «há diversas espécies de dons espirituais», 12:4ss.; 1Jo 5:16 e outros. Negativo <span class=\"greek\">οὐκ ἔστι</span>, «não existe; não há» (Sl 52:2; Simplício sobre Epicteto, p. 95, 42, citando uma «tragédia»: <span class=\"greek\">οὐκ εἰσὶν θεοί</span>, «não há deuses»): <span class=\"greek\">δίκαιος</span>, «justo», «não há justo», Rm 3:10 (Ec 7:20); <span class=\"greek\">ἀνάστασις νεκρῶν οὐκ ἔστιν</span>, «não há ressurreição de mortos», 1Co 15:12; <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">εἶναι ἀνάστασιν</span>, «nem existir ressurreição», AcPlCor 1:12; 2:24; cf. Mt 22:23; At 23:8 (cf. 2Mac 7:14). <span class=\"greek\">εἰσὶν οἵ</span> ou <span class=\"greek\">οἵτινες</span>, «há pessoas que» (Homero e outros; LXX; Justino, D. 47, 2: <span class=\"greek\">εἰ μήτι εἰσὶν οἱ λέγοντες ὅτι</span>, «a não ser que haja os que dizem que…». Com singular e plural combinados: Arriano, Ind. 24, 9: <span class=\"greek\">ἔστι δὲ οἳ διέφυγον</span>, «mas há alguns que escaparam»), Mt 16:28; 19:12; Mc 9:1; Lc 9:27; Jo 6:64; At 11:20. Negativo <span class=\"greek\">οὐδείς ἐστιν ὅς</span>, «não há ninguém que», Mc 9:39; 10:29; Lc 1:61; 18:29. Em pergunta <span class=\"greek\">τίς ἐστιν ὅς</span>;, «quem há que…?», Mt 12:11.</p>\n<p>Numa construção participial incomum (talvez terminologia administrativa), At 13:1: <span class=\"greek\">ἡ οὖσα ἐκκλησία</span>, «a congregação daquele lugar» (cf. Pseudo-Platão, Eryx. 6, 394c: <span class=\"greek\">οἱ ὄντες ἄνθρωποι</span>, «as pessoas com quem se tem de lidar»; PLond III 1168, 5, p. 136 [18 d.C.]: <span class=\"greek\">ἐπὶ ταῖς οὔσαις γειτνίαις</span>, «nas regiões contíguas existentes»; PGen 49; PSI 229, 11: <span class=\"greek\">τοῦ ὄντος μηνός</span>, «do mês corrente»); cf. At 14:13. <span class=\"greek\">αἱ οὖσαι</span> (subentenda-se <span class=\"greek\">ἐξουσίαι</span>), «as autoridades existentes», Rm 13:1 (cf. UPZ 180a I, 4 [113 a.C.]: <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἱερέων καὶ ἱερειῶν τῶν ὄντων καὶ οὐσῶν</span>).</p>\n<p><strong>② Estar em estreita conexão [com algo]; ser; função copulativa e equativa.</strong> Frequentemente em afirmações de identidade ou equivalência, como cópula, unindo sujeito e predicado. Sobre a ausência da cópula, Mlt-Turner 294–310.</p>\n<p><strong>ⓐ Em geral.</strong> <span class=\"greek\">πραΰς εἰμι</span>, «sou manso», Mt 11:29; <span class=\"greek\">ἐγώ εἰμι Γαβριήλ</span>, «eu sou Gabriel», Lc 1:19; <span class=\"greek\">σὺ εἶ ὁ υἱὸς τοῦ θεοῦ</span>, «tu és o Filho de Deus», Mc 3:11; Jo 1:49 e muito frequentemente. <span class=\"greek\">ἵνα</span> … <span class=\"greek\">ὁ πονηρὸς</span> … <span class=\"greek\">ἐλεγχθῇ</span> [<span class=\"greek\">το</span>? veja aparato em Bodm.] <span class=\"greek\">μὴ ὢν θεός</span>, «para que… o maligno… seja demonstrado não ser Deus», AcPlCor 2:15 (Justino, D. 3, 3: <span class=\"greek\">φιλολόγος οὖν τις εἶ σύ</span>, «então és um amante das letras»). O predicado pode ser suprido do contexto: <span class=\"greek\">καὶ ἐσμέν</span>, «e realmente somos [filhos de Deus]», 1Jo 3:1 (Eurípides, Ion 309: <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ καλοῦμαι δοῦλος εἰμί τε</span>, «sou chamado servo de Deus e o sou»; Díon Crisóstomo 14 [31], 58: <span class=\"greek\">θεοφιλεῖς οἱ χρηστοὶ λέγονται καὶ εἰσίν</span>, «os bons são chamados amados pelos deuses e assim são»; Epicteto 2, 16, 44: <span class=\"greek\">Ἡρακλῆς ἐπιστεύθη Διὸς υἱὸς εἶναι καὶ ἦν</span>, «Hércules era considerado filho de Zeus e o era»).</p>\n<p>O particípio <span class=\"greek\">ὤν</span>, <span class=\"greek\">οὖσα</span>, <span class=\"greek\">ὄν</span>, empregado com substantivo ou adjetivo, desempenha função de cópula em oração equivalente às introduzidas por «se», «uma vez que», ou «embora»: <span class=\"greek\">πονηροὶ ὄντες</span>, «sendo maus», Mt 7:11; 12:34; Lc 20:36; Jo 3:4; 4:9; At 16:21; Rm 5:10; 1Co 8:7; Gl 2:3 e outros.</p>\n<p>Com advérbio de qualidade: <span class=\"greek\">οὕτως εἶναι</span>, «ser assim», precedido de <span class=\"greek\">ὥσπερ</span> ou <span class=\"greek\">καθώς</span>, ou seguido de <span class=\"greek\">ὡς</span> ou <span class=\"greek\">ὥσπερ</span>, Mt 13:40; 24:27, 37, 39; Mc 4:26; Lc 17:26. Com dativo de pessoa: <span class=\"greek\">οὕτως ἔσται ὁ υἱὸς τ</span>. <span class=\"greek\">ἀ</span>. <span class=\"greek\">τῇ γενεᾷ ταύτῃ</span>, «assim será o Filho do Homem para esta geração», Lc 11:30. <span class=\"greek\">εἰμὶ ὡς</span> / <span class=\"greek\">ὥσπερ</span>, «sou como», Mt 6:5; Lc 18:11. Com dativo: <span class=\"greek\">ἔστω σοι ὥσπερ τελώνης</span>, «seja para ti como um publicano», Mt 18:17; <span class=\"greek\">εἰμὶ ὥς τις</span>, «sou como alguém», em semelhança exterior e interior, Mt 28:3; Lc 6:40; 11:44; 22:27 e outros. <span class=\"greek\">καθώς εἰμι</span>, «como sou», At 22:3; 1Jo 3:2, 7; 4:17.</p>\n<p>Com pronome demonstrativo (Justino, A I, 16, 1: <span class=\"greek\">ἃ ἔφη</span>, <span class=\"greek\">ταῦτά ἐστι</span>, seguido de citação; semelhantemente 48, 5: <span class=\"greek\">ἔστι δὲ ταῦτα</span>, e frequentemente): <span class=\"greek\">τὰ ὀνόματά ἐστιν ταῦτα</span>, «estes são os nomes», Mt 10:2; <span class=\"greek\">αὕτη ἐστὶν ἡ μαρτυρία</span>, «este é o testemunho», Jo 1:19. Seguido de infinitivo: <span class=\"greek\">θρησκεία αὕτη ἐστίν</span>, <span class=\"greek\">ἐπισκέπτεσθαι</span>, «esta é a religião: visitar», Tg 1:27. Seguido de <span class=\"greek\">ὅτι</span>: <span class=\"greek\">αὕτη ἐστὶν ἡ κρίσις</span>, <span class=\"greek\">ὅτι τὸ φῶς ἐλήλυθεν</span>, «este é o julgamento: que a luz veio», Jo 3:19; cf. 21:24; 1Jo 1:5; 3:11; 5:11. Seguido de <span class=\"greek\">ἵνα</span>: <span class=\"greek\">τοῦτό ἐστιν τὸ ἔργον</span>, <span class=\"greek\">ἵνα πιστεύητε</span>, «esta é a obra: que creiais», Jo 6:29; cf. versículos 39s.; 15:12; 17:3; 1Jo 3:11, 23; 5:3. Com <span class=\"greek\">τηλικοῦτος</span>: <span class=\"greek\">τὰ πλοῖα</span>, <span class=\"greek\">τηλικαῦτα ὄντα</span>, «os navios, embora tão grandes», Tg 3:4. Com <span class=\"greek\">τοσοῦτος</span>: <span class=\"greek\">τοσοῦτων ὄντων</span>, «embora fossem tantos», Jo 21:11. Com <span class=\"greek\">τοιοῦτος</span>: <span class=\"greek\">τοιοῦτος ὤν</span>, «sendo assim», Fm 9 (cf. Justino, A I, 18, 4: <span class=\"greek\">ὅσα ἄλλα τοιαῦτά ἐστι</span>).</p>\n<p>Com pronome interrogativo: <span class=\"greek\">ὑμεῖς τίνα με λέγετε εἶναι</span>;, «quem dizeis que eu sou?», Mt 16:15; cf. 21:10; Mc 1:24; 4:41; 8:27, 29; Lc 4:34 e outros; <span class=\"greek\">σὺ τίς εἶ</span>;, «quem és tu?», Jo 1:19; 8:25; 21:12 e outros (cf. JosAs 14:6: <span class=\"greek\">τίς εἶ συ</span>, «dize-me quem és»). <span class=\"greek\">σὺ τίς εἶ ὁ κρίνων</span>;, «quem és tu, que julgas?», Rm 14:4 (Platão, Gorg. 452b; Estrabão 6, 2, 4: <span class=\"greek\">σὺ τίς εἶ ὁ τὸν Ὅμηρον ψέγων ὡς μυθογράφον</span>;, «quem és tu, que censuras Homero como fabulador?»); <span class=\"greek\">ἐγὼ τίς ἤμην</span>;, «quem era eu?», At 11:17 (cf. Êx 3:11); <span class=\"greek\">τίς εἰμι ἐγὼ ὅτι</span>, «quem sou eu, para que…?», GJs 12:2 (Êx 3:11). Com <span class=\"greek\">πόσος</span>: <span class=\"greek\">πόσος χρόνος ἐστίν</span>;, «há quanto tempo?», Mc 9:21; com <span class=\"greek\">ποταπός</span>, «de que espécie», Lc 1:29. Com pronome relativo: <span class=\"greek\">οἷος</span>, 2Co 10:11; <span class=\"greek\">ὁποῖος</span>, At 26:29; 1Co 3:13; Gl 2:6; <span class=\"greek\">ὅς</span>, Ap 1:19; <span class=\"greek\">ὅστις</span>, Gl 5:10, 19.</p>\n<p>Com numerais: <span class=\"greek\">ἦσαν οἱ φαγόντες πεντακισχίλιοι ἄνδρες</span>, «os que comeram eram cinco mil homens», Mc 6:44 (cf. Polieno 7, 25: <span class=\"greek\">ἦσαν οἱ πεσόντες ἀνδρῶν μυριάδες δέκα</span>, «os homens mortos foram dez miríades»); cf. At 19:7; 23:13. <span class=\"greek\">Λάζαρος εἷς ἦν ἐκ τῶν ἀνακειμένων</span>, «Lázaro era um dos que estavam à mesa», Jo 12:2; cf. Gl 3:20; Tg 2:19. <span class=\"greek\">τῶν πιστευσάντων ἦν καρδία καὶ ψυχὴ μία</span>, «os que creram tinham um só coração e uma só alma», At 4:32. <span class=\"greek\">εἷς εἶναι</span>, «ser um e o mesmo», Gl 3:28; <span class=\"greek\">ἓν εἶναι</span>, «ser um», Jo 10:30; 17:11, 21ss.; 1Co 3:8. <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">εἶναι τὴν πλάσιν τὴν τῶν ἀνθρώπων τοῦ θεοῦ</span>, «nem ser a criação da humanidade obra de Deus», AcPlCor 1:13.</p>\n<p>Para estabelecer identidade, a fórmula <span class=\"greek\">ἐγώ εἰμι</span>, «eu sou», é frequentemente empregada nos evangelhos (correspondente ao hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">אֲנִי</bdi> <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">הוּא</bdi>, Dt 32:39; Is 43:10), de maneira que o predicado deve ser subentendido do contexto: Mt 14:27; Mc 6:50; 13:6; 14:62; Lc 22:70; Jo 4:26; 6:20; 8:24, 28; 13:19; 18:5s. e frequentemente; veja <span class=\"greek\">ἐγώ</span>. Em pergunta: <span class=\"greek\">μήτι ἐγώ εἰμι</span>;, «porventura sou eu?», com expectativa de resposta negativa, Mt 26:22, 25.</p>\n<p><strong>ⓑ Para descrever conexão especial entre sujeito e substantivo predicativo.</strong> <span class=\"greek\">ἡμεῖς ναὸς θεοῦ ἐσμεν ζῶντος</span>, «somos templo do Deus vivo», 2Co 6:16. <span class=\"greek\">ἡ ἐπιστολὴ ὑμεῖς ἐστε</span>, «vós sois nossa carta [de recomendação]», 3:2. <span class=\"greek\">σφραγίς μου τῆς ἀποστολῆς ὑμεῖς ἐστε</span>, «vós sois o selo do meu apostolado», 1Co 9:2, e frequentemente.</p>\n<p><strong>ⓒ Em explicações. <span class=\"greek\">α</span>. Para mostrar como alguma coisa deve ser compreendida: representar, equivaler a, significar.</strong> Também aqui <span class=\"greek\">εἰμί</span> é cópula. Geralmente se traduz «significar»; assim, na fórmula <span class=\"greek\">τοῦτ</span>’ <span class=\"greek\">ἔστιν</span>, «isto ou aquilo significa; isto é» (Epicteto, Ench. 33, 10; Arriano, Tact. 29, 3; SIG 880, 50; PFlor 157, 4; PSI 298, 9; PMert 91, 9; Josefo, C. Ap. 2, 16; ApcMos 19; Justino, D. 56, 23; 78, 3 e outros), Mc 7:2; At 19:4; Rm 7:18; 9:8; 10:6, 8; Fm 12; Hb 7:5 e outros; «isto é [quando traduzido]» (Polieno 8, 14, 1: <span class=\"greek\">Μάξιμος ἀνηγορεύθη</span>· <span class=\"greek\">τοῦτο δ</span>’ <span class=\"greek\">ἄν εἴη Μέγιστον</span>, «foi chamado Máximo; isto equivaleria a Maior»), Mt 27:46; At 1:19. Assim também com pronome relativo <span class=\"greek\">ὅ ἐστιν</span>, «que significa», Mc 3:17; 7:11, 34; Hb 7:2.</p>\n<p>Após verbos de perguntar, reconhecer, saber e ignorar (Antífanes, Com. 231, 1s.: <span class=\"greek\">τὸ ζῆν τί ἐστι</span>;, «o que significa viver?»): <span class=\"greek\">μάθετε τί ἐστιν</span>, «aprendei o que [isto] significa», Mt 9:13. <span class=\"greek\">εἰ ἐγνώκειτε τί ἐστιν</span>, «se soubésseis o que significa», 12:7; cf. Mc 1:27; 9:10; Lc 20:17; Jo 16:17s.; Ef 4:9. Com pergunta indireta (Estêvão de Bizâncio, s.v. <span class=\"greek\">Ἀγύλλα</span>: <span class=\"greek\">τὶς ἠρώτα τί ἂν εἴη τὸ ὄνομα</span>, «alguém perguntou o que significava o nome»): <span class=\"greek\">τί ἂν εἴη ταῦτα</span>, Lc 15:26; <span class=\"greek\">τί εἴη τοῦτο</span>, 18:36; <span class=\"greek\">τίνα θέλει ταῦτα εἶναι</span>, «o que isto significa», At 17:20; cf. 2:12, onde a pergunta não se refere ao significado de termos, mas à importância do que está acontecendo.</p>\n<p>Especialmente na interpretação de parábolas (Artemidoro 1, 51, p. 48, 26: <span class=\"greek\">ἄρουρα οὐδὲν ἄλλο ἐστὶν ἢ γυνή</span>, «campo não significa outra coisa senão mulher»): <span class=\"greek\">ὁ ἀγρός ἐστιν ὁ κόσμος</span>, «o campo significa o mundo», Mt 13:38; cf. versículos 19s., 22s.; Mc 4:15s., 18, 20; Lc 8:11ss. (cf. Gn 41:26s.; Ez 37:11; Ath. 22, 4 [interpretação estoica de mitos]). Sobre <span class=\"greek\">τοῦτό ἐστιν τὸ σῶμά μου</span>, «isto é o meu corpo», Mt 26:26; Mc 14:22; Lc 22:19, e suas diversas interpretações, veja a bibliografia em <span class=\"greek\">εὐχαριστία</span>. Cf. Hipônax (século VI a.C.), 45 Diehl: <span class=\"greek\">αὕτη γάρ ἐστι συμφορή</span>, «isto significa desgraça».</p>\n<p><strong><span class=\"greek\">β</span>. Ter importância ou relevância relativa; ser significativo, equivaler a alguma coisa.</strong> Com pronome indefinido: <span class=\"greek\">εἰδωλόθυτόν τί ἐστιν</span>, «o alimento sacrificado aos ídolos significa alguma coisa», 1Co 10:19. Especialmente <span class=\"greek\">εἰμί τι</span>, «ser alguém / ter alguma importância», de pessoas, 1Co 3:7; Gl 2:6; 6:3; de coisas, versículo 15. <span class=\"greek\">εἰμί τις</span>, At 5:36. — «Não ter importância»: <span class=\"greek\">ἐμοὶ εἰς ἐλάχιστόν ἐστιν</span>, «para mim é de importância mínima ou nenhuma», 1Co 4:3 (contração de <span class=\"greek\">ἐλάχιστον ἐστιν</span> e <span class=\"greek\">εἰς ἐλάχιστον γίνεται</span>, com muitos exemplos em Schmid I 398; II 161, 237; III 281; IV 455).</p>\n<p><strong>③ Ser em relação a localidade, pessoas, condição ou tempo; estar, encontrar-se.</strong></p>\n<p><strong>ⓐ Em diversas relações ou posições envolvendo um lugar ou coisa.</strong> Com <span class=\"greek\">ἀπό</span>: <span class=\"greek\">εἶναι ἀπό τινος</span>, «ser ou vir de determinado lugar» (Xenofonte, An. 2, 4, 13), Jo 1:44. — Com <span class=\"greek\">ἐν</span>: <span class=\"greek\">ἐν τοῖς τ</span>. <span class=\"greek\">πατρός μου</span>, «na casa de meu Pai», Lc 2:49 (cf. Josefo, Ant. 16, 302, <span class=\"greek\">καταγωγὴ ἐν τοῖς Ἀντιπάτρου</span>); <span class=\"greek\">ἐν τῇ ὁδῷ</span>, «no caminho», Mc 10:32; <span class=\"greek\">ἐν τῇ ἐρήμῳ</span>, «no deserto», Mt 24:26; <span class=\"greek\">ἐν ἀγρῷ</span>, «no campo», Lc 15:25; <span class=\"greek\">ἐν δεξιᾷ τ</span>. <span class=\"greek\">θεοῦ</span>, «à direita de Deus», Rm 8:34; no céu, Ef 6:9. — Com <span class=\"greek\">εἰς</span>: <span class=\"greek\">τὴν κοίτην</span>, «na cama», Lc 11:7; <span class=\"greek\">τὸν κόλπον</span>, «no seio», Jo 1:18. — Com <span class=\"greek\">ἐπί</span> e genitivo: «estar sobre algo», por exemplo, sobre o telhado, Lc 17:31; sobre a cabeça, Jo 20:7 (cf. 1Mac 1:59); também figuradamente acerca daquele que está sobre outra pessoa (1Mac 10:69; Jd 14:13: <span class=\"greek\">ὁ ὢν ἐπὶ πάντων τῶν αὐτοῦ</span>, «o que está sobre todos os seus»), Rm 9:5 (sobre o anjo da morte, Melitão, P. 20, 142, <span class=\"greek\">ἐπὶ τῶν πρωτοτόκων</span>, «sobre os primogênitos»); também <span class=\"greek\">ἐπάνω τινός</span>, Jo 3:31. — Com dativo: «estar junto a algo», à porta, Mt 24:33; Mc 13:29. — Com acusativo: «estar sobre alguém», a graça, Lc 2:40; At 4:33; o espírito (Is 61:1), Lc 2:25; <span class=\"greek\">εἶναι ἐπὶ τὸ αὐτό</span>, «estar no mesmo lugar, juntos» (Gn 29:2, variante), At 1:15; 2:1, 44; 1Co 7:5.</p>\n<p>Com <span class=\"greek\">κατά</span> e acusativo: <span class=\"greek\">εἶναι κατὰ τὴν Ἰουδαίαν</span>, «estar na Judeia», At 11:1; <span class=\"greek\">εἶναι ἐν Ἀντιοχείᾳ κατὰ τὴν οὖσαν ἐκκλησίαν</span>, «estavam em Antioquia, na congregação de lá», 13:1. — Com <span class=\"greek\">ὑπό</span> e acusativo de coisa ou pessoa: «estar debaixo de algo», Jo 1:48; 1Co 10:1. — Com <span class=\"greek\">παρά</span> e acusativo: <span class=\"greek\">παρὰ τὴν θάλασσαν</span>, «junto à margem do mar [isto é, lago]», Mc 5:21; At 10:6. — Com <span class=\"greek\">πρός τι</span>: «estar perto de, defronte de», Mc 4:1. — Com advérbios de lugar: <span class=\"greek\">ἐγγύς τινι</span>, «perto de alguma coisa», At 9:38; 27:8; <span class=\"greek\">μακράν</span> (<span class=\"greek\">ἀπό</span>), «longe», Mc 12:34; Jo 21:8; Ef 2:13; também <span class=\"greek\">πόρρω</span>, Lc 14:32; <span class=\"greek\">χωρίς τινος</span>, «sem alguma coisa», Hb 12:8; <span class=\"greek\">ἐνθάδε</span>, «aqui», At 16:28; <span class=\"greek\">ἔσω</span>, «dentro», Jo 20:26; <span class=\"greek\">ἀπέναντί τινος</span>, «em frente de», Rm 3:18 (Sl 35:2); <span class=\"greek\">ἐκτός τινος</span>, «fora de», 1Co 6:18; <span class=\"greek\">ἀντίπερά τινος</span>, «defronte de», Lc 8:26; <span class=\"greek\">ὁμοῦ</span>, «juntos», Jo 21:2; <span class=\"greek\">οὗ</span>, «onde», Mt 2:9; <span class=\"greek\">ὅπου</span>, Mc 2:4; 5:40; <span class=\"greek\">ὧδε</span>, «aqui», Mt 17:4; Mc 9:5; Lc 9:33.</p>\n<p>Também com sentido de futuro (E. Schwartz, GGN 1908, 161, nota; quanto ao emprego futuro do presente, cf. POxy 531, 22 [século II d.C.]: <span class=\"greek\">ἔστι δὲ τοῦ Τῦβι μηνὸς σοὶ ὸ̔ θέλεις</span>), <span class=\"greek\">ὅπου εἰμί</span>, «onde estarei», Jo 7:34, 36; 12:26; 14:3; 17:24. Como predicado para designar permanência relativamente longa num lugar: <strong>permanecer, residir</strong>; <span class=\"greek\">ἴσθι ἐκεῖ</span>, «permanece ali», Mt 2:13, cf. versículo 15; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐρήμοις τόποις</span>, «em lugares solitários», Mc 1:45; <span class=\"greek\">ἦν παρὰ τὴν θάλασσαν</span>, «permanecia junto à margem do lago», Mc 5:21.</p>\n<p><strong>ⓑ Envolvendo seres humanos ou transcendentes.</strong> Com advérbio: <span class=\"greek\">ἔμπροσθέν τινος</span>, «diante de alguém», Lc 14:2; <span class=\"greek\">ἔναντί τινος</span>, «perante alguém», At 8:21; <span class=\"greek\">ἐνώπιόν τινος</span>, «diante de alguém», Lc 14:10; At 4:19; 1Pe 3:4; Ap 7:15; <span class=\"greek\">ἐντός τινος</span>, «dentro de alguém», Lc 17:21; <span class=\"greek\">ἐγγύς τινος</span>, «perto de alguém», Jo 11:18; 19:20; Rm 10:8 (Dt 30:14).</p>\n<p>Com preposição: <span class=\"greek\">ἐν τινί</span>, equivalente a <span class=\"greek\">ἔκ τινος εἶναι</span>, «estar entre», Mt 27:56; cf. Mc 15:40; Rm 1:6. Referente a Deus entre seu povo, 1Co 14:25 (Is 45:14; Jr 14:9); ao Espírito, Jo 14:17. De pessoas sob a direção de Cristo: <span class=\"greek\">ἐν θεῷ</span>, «em Deus», 1Jo 2:5; 5:20 (veja Norden, Agnostos Theos 23, nota 1). <span class=\"greek\">ἔν τινι</span>, «repousar sobre, originar-se de alguma coisa» (Aristóteles, Pol. 7, 1, 3 [1323b, 1]: <span class=\"greek\">ἐν ἀρετῇ</span>, «na virtude»; Sir 9:16), At 4:12; 1Co 2:5; Ef 5:18.</p>\n<p><span class=\"greek\">εἴς τινα</span>, «ser dirigido, inclinado a alguém», At 23:30; 2Co 7:15; 1Pe 1:21. — <span class=\"greek\">κατά</span> com genitivo, «estar contra alguém» (Sir 6:12), Mt 12:30; Mc 9:40 e Lc 9:50 (ambos em oposição a <span class=\"greek\">ὑπέρ</span>); Gl 5:23. — <span class=\"greek\">σύν τινι</span>, «estar com alguém» (Josefo, Ant. 7, 181), Lc 22:56; 24:44; At 13:7; «acompanhar, associar-se a alguém», Lc 8:38; At 4:13; 22:9; «tomar partido de alguém» (Xenofonte, Cyr. 5, 4, 37; 7, 5, 77; Josefo, Ant. 11, 259 [referente a Deus]), At 14:4. — <span class=\"greek\">πρός τινα</span>, «estar com alguém», Mt 13:56; Mc 6:3; Jo 1:1s.; compare IMg 12.</p>\n<p><span class=\"greek\">μετά</span> e genitivo, «estar com alguém» (Jz 14:11), Mt 17:17; Mc 3:14; 5:18; Jo 3:26; 12:17; <span class=\"greek\">ἔστω μεθ</span>’ <span class=\"greek\">ὑμῶν εἰρήνη</span>, «seja convosco a paz», AcPlCor 2:40; de Deus presente com alguém (Gn 21:20; Jz 6:13 e outros; Fílon, Det. Pot. Ins. 4; Josefo, Ant. 6, 181; 15, 138), Lc 1:66; Jo 3:2; 8:29; At 10:38 e outros. Também «estar com» no sentido de «ser favorável, estar aliado a» (Êx 23:2), Mt 12:30; Lc 11:23. De castigo que acompanha alguém: <span class=\"greek\">τὸ πῦρ ἐστι μετ</span>’ <span class=\"greek\">αὐτοῦ</span>, «o fogo está com ele», AcPlCor 2:37.</p>\n<p><span class=\"greek\">παρά</span> e genitivo, «vir de alguém» (Xenofonte, An. 2, 4, 15; Justino, D. 8, 4: <span class=\"greek\">ἔλεος παρὰ θεοῦ</span>, «misericórdia de Deus»); de Deus, Jo 6:46; 7:29. Com dativo: «estar com, entre pessoas», Mt 22:25; At 10:6; com negação, «ser estranho a alguém; não haver… em alguém», Rm 2:11; 9:14; Ef 6:9. — <span class=\"greek\">ὑπέρ</span> com genitivo: «estar do lado de alguém», Mc 9:4 e Lc 9:50 (ambos em oposição a <span class=\"greek\">κατά</span>); com acusativo, «ser superior a» (Sir 25:10; 30:16), Lc 6:40.</p>\n<p><strong>ⓒ De condição ou circunstância.</strong> <span class=\"greek\">κατά</span> com acusativo, «viver de acordo com» (Sir 28:10; 43:8; 2Mac 9:20): <span class=\"greek\">κατὰ σάρκα</span>, <span class=\"greek\">πνεῦμα</span>, «segundo a carne, o espírito», Rm 8:5. <span class=\"greek\">οὐκ ἔστιν κατὰ ἄνθρωπον</span>, «não é de origem humana», Gl 1:11. — Figuradamente, <span class=\"greek\">ὑπό</span> com acusativo, «estar sob [o poder de] alguma coisa», Rm 3:9; 6:14s.; Gl 3:10, 25. — Com <span class=\"greek\">ἐν</span> indicando existência: <span class=\"greek\">ἐν τῷ θεῷ εἶναι</span>, referente à humanidade, «ter sua existência fundamentada em Deus», At 17:28.</p>\n<p>De estados de ser: <span class=\"greek\">ἐν δόξῃ</span>, «em glória», 2Co 3:8; <span class=\"greek\">ἐν εἰρήνῃ</span>, «em paz», Lc 11:21; <span class=\"greek\">ἐν ἔχθρᾳ</span>, «em inimizade», 23:12; <span class=\"greek\">ἐν κρίματι</span>, «sob condenação», versículo 40; <span class=\"greek\">ἐν ῥύσει αἵματος</span>, «sofrer hemorragias», Mc 5:25; Lc 8:43 (cf. Sófocles, Aj. 271: <span class=\"greek\">ἦν ἐν τῇ νόσῳ</span>, «estava enfermo»; cf. TestJob 35:1: <span class=\"greek\">ἐν πληγαῖς πολλαῖς</span>, «em muitas feridas»). Perífrase equivalente a adjetivo: <span class=\"greek\">ἐν ἐξουσίᾳ</span>, «com autoridade», Lc 4:32; <span class=\"greek\">ἐν βάρει</span>, «importante», 1Ts 2:7; <span class=\"greek\">ἐν τῇ πίστει</span>, «verdadeiros crentes, crentes», 2Co 13:5.</p>\n<p>«Estar envolvido em alguma coisa»: <span class=\"greek\">ἐν ἑορτῇ</span>, «estar na festa» = «participar dela», Jo 2:23; <span class=\"greek\">ἐν τούτοις ἴσθι</span>, «dedica-te a estas coisas», 1Tm 4:15 (cf. Xenofonte, Hell. 4, 8, 7: <span class=\"greek\">ἐν τοιούτοις ὄντες</span>, «ocupados com essas coisas»; Josefo, Ant. 2, 346: <span class=\"greek\">ἐν ὕμνοις ἦσαν</span>, «ocupavam-se em cantar hinos»). Figuradamente, «viver na luz», 1Jo 2:9; cf. versículo 11; 1Ts 5:4; «na carne», Rm 7:5; 8:8; AcPlCor 1:6. <span class=\"greek\">ἐν οἷς εἰμι</span>, «na situação em que me encontro», Fp 4:11 (Xenofonte, Hell. 4, 2, 1; Diodoro Sículo 12, 63, 5; 12, 66, 4; Apiano, Hann. 55 §228: <span class=\"greek\">ἐν τούτοις ἦν</span>, «achava-se nessa situação»; Josefo, Ant. 7, 232: <span class=\"greek\">ἐν τούτοις ἦσαν</span>, «encontravam-se nessa situação»; TestJob 35:6: <span class=\"greek\">ἐν τίνι ἐστίν</span>; veja ZPE VIII 170). <span class=\"greek\">ἐν πολλοῖς ὢν ἀστοχήμασι</span>, «encontrando-me entre muitos fracassos», AcPlCor 2:1. De características, emoções etc., <span class=\"greek\">ἔν τινί ἐστιν</span>, «há em alguém», por exemplo <span class=\"greek\">ἀδικία</span>, «injustiça», Jo 7:18; <span class=\"greek\">ἄγνοια</span>, «ignorância», Ef 4:18; <span class=\"greek\">ἀλήθεια</span>, «verdade», Jo 8:44; 2Co 11:10 (cf. 1Mac 7:18); <span class=\"greek\">ἁμαρτία</span>, «pecado», 1Jo 3:5.</p>\n<p><strong>ⓓ De tempo.</strong> <span class=\"greek\">ἐγγύς</span>, acerca de <span class=\"greek\">καιρός</span>, «tempo», «estar próximo», Mt 26:18; Mc 13:28. <span class=\"greek\">πρὸς ἑσπέραν ἐστίν</span>, «está chegando a tarde», Lc 24:29 (Justino, D. 137, 4: <span class=\"greek\">πρὸς δυσμὰς</span> … <span class=\"greek\">ὁ ἥλιός ἐστι</span>, «o sol está perto do ocaso»).</p>\n<p><strong>④ Estar vivo em determinado período; viver, designando existência temporal.</strong> (Homero, trágicos, Tucídides e outros; Sir 42:21; En 102:5; Fílon, De Jos. 17; Josefo, Ant. 7, 254.) <span class=\"greek\">εἰ ἤμεθα ἐν ταῖς ἡμέραις τῶν πατέρων ἡμῶν</span>, «se tivéssemos vivido nos dias de nossos pais», Mt 23:30; <span class=\"greek\">ὅτι οὐκ εἰσὶν</span>, «porque já não existem», Mt 2:18 (Jr 38:15); <span class=\"greek\">ἦσαν ἐπὶ χρόνον ἱκανόν</span>, «[os curados e ressuscitados por Cristo] permaneceram vivos por considerável tempo», Qua.</p>\n<p><strong>⑤ Indicar o momento em que algo ocorre; ser [determinada hora ou ocasião].</strong> (Xenofonte, Hell. 4, 5, 1; An. 4, 3, 8; Sus 13, Teodócio; 1Mac 6:49; 2Mac 8:26; Josefo, Ant. 6, 235: <span class=\"greek\">νουμηνία δ</span>’ <span class=\"greek\">ἦν</span>, «era lua nova»; 11, 251.) <span class=\"greek\">ἦν ὥρα ἕκτη</span>, «era a sexta hora» (= meio-dia, segundo o cômputo judaico), Lc 23:44; Jo 4:6; 19:14; Mc 15:25; Jo 1:39. <span class=\"greek\">ἦν ἑσπέρα ἤδη</span>, «já era tarde», At 4:3; <span class=\"greek\">πρωί̈</span>, «de manhã cedo», Jo 18:28; <span class=\"greek\">ἦν παρασκευή</span>, «era o dia da preparação», Mc 15:42; <span class=\"greek\">ἦν ἑορτὴ τῶν Ἰουδαίων</span>, «era festa dos judeus», Jo 5:1; <span class=\"greek\">σάββατόν ἐστιν</span>, «é sábado», versículo 10 e outros.</p>\n<p>Em frases curtas (como Polieno 4, 9, 2: <span class=\"greek\">νὺξ ἦν</span>, «era noite»; 7, 44, 2: <span class=\"greek\">πόλεμος ἦν</span>, «era guerra»; excerto 36, 8: <span class=\"greek\">ἦν ἀρίστου ὥρα</span>, «era hora do almoço»; Josefo, Ant. 19, 248: <span class=\"greek\">ἔτι δὲ νὺξ ἦν</span>, «ainda era noite»): <span class=\"greek\">χειμὼν ἦν</span>, «era inverno», Jo 10:22; <span class=\"greek\">ἦν δὲ νύξ</span>, «era noite» (semelhantemente Josefo, Bell. 4, 64), Jo 13:30; <span class=\"greek\">ψύχος</span>, «fazia frio», 18:18; <span class=\"greek\">καύσων ἔσται</span>, «fará calor», Lc 12:55.</p>\n<p><strong>⑥ Acontecer como fenômeno ou evento; ocorrer, suceder, tornar-se, haver.</strong> (Homero, Tucídides e outros; LXX; En 104:5; 106:6; cf. Justino, D. 82, 2, sobre as predições de Cristo: <span class=\"greek\">ὅπερ καὶ ἔστι</span>, «o que de fato ocorre».) <span class=\"greek\">ἔσται θόρυβος τοῦ λαοῦ</span>, «haverá revolta popular», Mc 14:2; <span class=\"greek\">γογγυσμὸς ἦν</span>, «havia muita murmuração», Jo 7:12; <span class=\"greek\">σχίσμα</span>, «houve divisão», Jo 9:16; 1Co 1:10; 12:25; <span class=\"greek\">ἔριδες</span> … <span class=\"greek\">εἰσίν</span>, «há contendas», 1Co 1:11; <span class=\"greek\">δεῖ αἱρέσεις εἶναι</span>, «é necessário haver facções», 11:19; <span class=\"greek\">θάνατος</span>, <span class=\"greek\">πένθος</span>, <span class=\"greek\">κραυγή</span>, <span class=\"greek\">πόνος ἔσται</span>, «haverá morte, pranto, clamor, dor», Ap 21:4; <span class=\"greek\">ἔσονται λιμοὶ κ</span>. <span class=\"greek\">σεισμοί</span>, «haverá fomes e terremotos», Mt 24:7. Daí <span class=\"greek\">τὸ ἐσόμενον</span>, «o que haveria de acontecer» (Sir 48:25), Lc 22:49; <span class=\"greek\">πότε ταῦτα ἔσται</span>;, «quando acontecerão essas coisas?», Mt 24:3; <span class=\"greek\">πῶς ἔσται τοῦτο</span>;, «como será isso?», Lc 1:34.</p>\n<p>Hebraísmo (<bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">הָיָה</bdi>; veja K. Beyer, Semitische Syntax im NT, 1962, 63–65): <span class=\"greek\">καὶ ἔσται</span>, seguido do futuro de outro verbo, «e acontecerá que», At 2:17 (Jl 3:1); 3:23 (com <span class=\"greek\">δέ</span>); Rm 9:26 (Os 2:1). — Com dativo: <span class=\"greek\">ἐστί τινι</span>, «acontecer, ser concedido ou ocorrer a alguém» (Xenofonte, An. 2, 1, 10; Josefo, Ant. 11, 255; Justino, D. 8, 4: <span class=\"greek\">σοὶ</span> … <span class=\"greek\">ἔλεος ἔσται παρὰ θεοῦ</span>, «terás misericórdia de Deus»), Mt 16:22; Mc 11:24; Lc 2:10; GJs 1:1; 4:3; 8:3; <span class=\"greek\">τί ἐστίν σοι τοῦτο</span>, <span class=\"greek\">ὅτι</span>, «que te acontece, para que…?», GJs 17:2.</p>\n<p>De <strong>tornar-se alguma coisa, converter-se em algo</strong>: <span class=\"greek\">εἰς χολὴν πικρίας εἶναι</span>, «tornar-se fel amargo», At 8:23; <span class=\"greek\">εἰς σάρκα μίαν</span>, «[tornar-se] uma só carne», Mt 19:5; Mc 10:8; 1Co 6:16; Ef 5:31 (todos Gn 2:24; cf. Sintipas, p. 42, 24: <span class=\"greek\">οὐκ ἔτι ἔσομαι μετὰ σοῦ εἰς γυναῖκα</span>, «já não serei tua mulher»); <span class=\"greek\">τὰ σκολιὰ εἰς εὐθείας</span>, «os caminhos tortuosos [se tornarão] retos», Lc 3:5 (Is 40:4); <span class=\"greek\">εἰς πατέρα</span>, «[ser] pai», 2Co 6:18; Hb 1:5 (2Rs 7:14; 1Cr 22:10; 28:6); <span class=\"greek\">εἰς τὸ ἕν</span>, «em uma só coisa», 1Jo 5:8.</p>\n<p><strong>Servir como alguma coisa</strong> (IPriene 50, 39 [cerca do século II a.C.]: <span class=\"greek\">εἶναι εἰς φυλακὴν τ</span>. <span class=\"greek\">πόλεως</span>, «servir para a defesa da cidade»; Esopo, Fab. 28 H. = 18 P. = 26 Ch. = 18 H-H.: <span class=\"greek\">εἰς ὠφέλειαν</span>, «para proveito»; Gn 9:13; veja também <span class=\"greek\">εἰς</span> 4d), 1Co 14:22; Cl 2:22; Tg 5:3. De alguma coisa «ser»: <span class=\"greek\">ἀνεκτότερον ἔσται</span>, «será mais tolerável», com dativo <span class=\"greek\">τινί</span>, «para alguém», Lc 10:12, 14.</p>\n<p><strong>⑦ Existir como possibilidade; <span class=\"greek\">ἔστιν</span> seguido de infinitivo: ser possível, poder-se.</strong> (<span class=\"greek\">Περὶ ὕψους</span> 6; Diógenes Laércio 1, 110: <span class=\"greek\">ἔστιν εὑρεῖν</span>, «pode-se encontrar»; Justino, A I, 59, 10: <span class=\"greek\">ἔστι ταῦτα ἀκοῦσαι καὶ μαθεῖν</span>, «é possível ouvir e aprender essas coisas»; D. 42, 3: <span class=\"greek\">ἰδεῖν</span>, «ver», e outros; Melitão, P. 19, 127.) Negativo: <span class=\"greek\">οὐκ ἔστιν νῦν λέγειν</span>, «não é possível falar agora», Hb 9:5; <span class=\"greek\">οὐκ ἔστιν φαγεῖν</span>, «é impossível comer», 1Co 11:20 (assim Homero e outros; UPZ 70, 23 [152/151 a.C.]: <span class=\"greek\">οὐκ ἔστι ἀνακύψαι με πώποτε</span> … <span class=\"greek\">ὑπὸ τῆς αἰσχύνης</span>, «não poderei jamais erguer a cabeça de vergonha»; 4Mac 13:5; Sb 5:10; Sir 14:16; 18:6; EpJer 49 e outros; EpArist 163; Josefo, Ant. 2, 335; Ath. 22, 3: <span class=\"greek\">ἔστιν εἰπεῖν</span>, «pode-se dizer»).</p>\n<p><strong>⑧ Ter ponto de derivação ou origem; ser, vir de algum lugar.</strong> <span class=\"greek\">ἐκ τῆς ἐξουσίας Ἡρῴδου</span>, «da jurisdição de Herodes», Lc 23:7; <span class=\"greek\">ἐκ Ναζαρέτ</span>, «de Nazaré», como lugar sem importância, Jo 1:46; <span class=\"greek\">ἐκ τῆς γῆς</span>, «da terra», 3:31; <span class=\"greek\">ἐκ γυναικός</span>, «de mulher», 1Co 11:8 e outros. <span class=\"greek\">ἐξ οὐρανοῦ</span>, <span class=\"greek\">ἐξ ἀνθρώπων</span>, «de procedência celeste [divina] ou humana», Mt 21:25; Mc 11:30; Lc 20:4. «Ser gerado por» (cf. Sb 8141, 21s. [inscrição do século I a.C.]: <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ἐκ βροτοῦ ἤεν ἄνακτος</span>, <span class=\"greek\">ἀλλὰ θεοῦ μεγάλου ἔκγονος</span>, «não descendia de senhor mortal, mas do grande deus»; En 106:6), Mt 1:20.</p>\n<p>Especialmente na linguagem joanina: <span class=\"greek\">ἐκ τοῦ διαβόλου εἶναι</span>, «ter origem no diabo», Jo 8:44; 1Jo 3:8; <span class=\"greek\">ἐκ τοῦ πονηροῦ</span>, «do maligno», 1Jo 3:12; <span class=\"greek\">ἐκ τοῦ κόσμου</span>, «do mundo», Jo 15:19; 17:14, 16; 1Jo 4:5; <span class=\"greek\">ἐκ τῆς ἀληθείας εἶναι</span>, «ser da verdade», 1Jo 2:21; Jo 18:37 e outros. Cf. o fim de ⑨.</p>\n<p><strong>⑨ Pertencer a alguém ou a alguma coisa por associação ou vinculação genealógica; ser, pertencer.</strong> Com genitivo simples (Xenofonte, Hell. 2, 4, 36; Jâmblico, Vi. Pyth. 33, 230: <span class=\"greek\">τῶν Πυθαγορείων</span>, «dos pitagóricos»): <span class=\"greek\">οἱ τῆς ὁδοῦ ὄντες</span>, «os pertencentes ao Caminho», At 9:2; <span class=\"greek\">εἰμὶ Παύλου</span>, «sou de Paulo», 1Co 1:12; 3:4; cf. Rm 8:9; 2Co 10:7; 1Tm 1:20; At 23:6. <span class=\"greek\">ἡμέρας εἶναι</span>, «pertencer ao dia», 1Ts 5:8, cf. versículo 5. Com <span class=\"greek\">ἔκ τινος</span>, 1Co 12:15s.; Mt 26:73; Mc 14:69s.; Lc 22:58 e outros (cf. Xenofonte, Mem. 3, 6, 17; frequentemente na LXX). <span class=\"greek\">ἐκ τοῦ ἀριθμοῦ τῶν δώδεκα</span>, «pertencer ao número dos Doze», Lc 22:3. <span class=\"greek\">ὅς ἐστιν ἐξ ὑμῶν</span>, «que é vosso compatriota», Cl 4:9. — Pertencer por origem, 2Co 4:7. De Maria: <span class=\"greek\">ἦν τῆς φυλῆς τοῦ Δαυίδ</span>, «era da linhagem de Davi», GJs 10:1. Cf. ⑧ acima.</p>\n<p><strong>⑩ Ter relação com alguma coisa ou alguém; ser.</strong> Para designar ligação estreita: <span class=\"greek\">ἐξ ἔργων νόμου εἶναι</span>, «apoiar-se na observância da lei», Gl 3:10; <span class=\"greek\">ὁ νόμος οὐκ ἔστιν ἐκ πίστεως</span>, «a lei nada tem a ver com a fé», versículo 12. — Para designar possuidor: Mt 5:3, 10; 19:14; Mc 12:7; Lc 18:16; 1Co 6:19. Especialmente Deus como possuidor dos cristãos: At 27:23; 1Co 3:23; 2Tm 2:19 (Nm 16:5). <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">εἶναι τὸν κόσμον θεοῦ</span>, <span class=\"greek\">ἀλλὰ ἀγγέλων</span>, «nem ser o mundo de Deus, mas dos anjos», AcPlCor 1:15 (cf. Justino, A II, 13, 4: <span class=\"greek\">ὅσα</span> … <span class=\"greek\">καλῶς εἴρηται</span>, <span class=\"greek\">ἡμῶν τῶν χριστιανῶν ἐστι</span>, «quanto foi bem dito pertence a nós, cristãos»). — Com pronome possessivo: <span class=\"greek\">ὑμετέρα ἐστὶν ἡ βασιλεία</span>, «vosso é o Reino», Lc 6:20; <span class=\"greek\">οὐκ ἔστιν ἐμὸν δοῦναι</span>, «não me compete conceder», Mc 10:40 (cf. Justino, A I, 4, 2: <span class=\"greek\">ὑμέτερον ἀγωνιᾶσαί ἐστι</span>, «compete-vos preocupar-vos»). — Para designar função (Xenofonte, An. 2, 1, 4): <span class=\"greek\">οὐχ ὑμῶν ἐστιν</span>, «não vos compete», At 1:7. — Para designar qualidade: <span class=\"greek\">παιδεία οὐ δοκεῖ χαρᾶς εἶναι</span>, «a disciplina não parece participar da alegria», Hb 12:11; 10:39.</p>\n<p><strong>⑪ Como verbo auxiliar:</strong> muito frequentemente as formas dos tempos simples são substituídas pela perífrase de <span class=\"greek\">εἶναι</span> e particípio (B-D-F §§352–355; Mlt. 225–227, 249; Mlt-H. 451s.; Rdm.² 102, 105, 205; Kühner-G. I 38ss.; Rob. 374–376, 1119s.; C. Turner, Marcan Usage: JTS 28, 1927, 349–351; G. Kilpatrick, BT 7, 1956, 7s.; muito frequentemente na LXX).</p>\n<p><strong>ⓐ Com particípio perfeito</strong> (como em Homero e outros) para expressar perfeito, mais-que-perfeito e futuro perfeito, ativos e passivos (veja Mayser 329; 377): <span class=\"greek\">ἦσαν ἐληλυθότες</span>, «tinham vindo», Lc 5:17; <span class=\"greek\">ἦν αὐτῶν ἡ καρδία πεπωρωμένη</span>, «o coração deles estava endurecido», Mc 6:52; <span class=\"greek\">ἠλπικότες ἐσμέν</span>, «temos posto nossa esperança», 1Co 15:19; <span class=\"greek\">ὁ καιρὸς συνεσταλμένος ἐστίν</span>, «o tempo se tornou curto», 7:29; <span class=\"greek\">ἦν ἑστώς</span> (En 12:3), «estava de pé» (mais exatamente, «colocou-se de pé»), Lc 5:1.</p>\n<p><strong>ⓑ Com particípio presente</strong> (B-D-F §353). <strong><span class=\"greek\">α</span>.</strong> Para expressar o presente: <span class=\"greek\">ἐστὶν προσαναπληροῦσα τὰ ὑστερήματα</span>, «supre as necessidades», 2Co 9:12 (Justino, A I, 26, 5: <span class=\"greek\">Μαρκίων</span> … <span class=\"greek\">καὶ νῦν ἔτι ἐστὶ διδάσκων</span>, «Marcião… continua ensinando até hoje»; Melitão, P. 61, 441: <span class=\"greek\">ἐστὶν</span> … <span class=\"greek\">κηρυσσόμενον</span>, «está sendo proclamado»). <strong><span class=\"greek\">β</span>.</strong> Para expressar imperfeito ou aoristo: <span class=\"greek\">ἦν καθεύδων</span>, «estava dormindo», Mc 4:38; <span class=\"greek\">ἦσαν ἀναβαίνοντες</span> … <span class=\"greek\">ἦν προάγων</span>, «estavam subindo… ia adiante», 10:32; cf. Lc 1:22; 5:17; 11:14 e outros (JosAs 1:3: <span class=\"greek\">ἦν συνάγων τὸν σίτον</span>, «estava colhendo o trigo»; Melitão, P. 80, 580: <span class=\"greek\">ἦσθα εὐφραινόμενος</span>, «estavas alegrando-te»); <span class=\"greek\">ἦν τὸ φῶς τὸ ἀλήθινόν</span> … <span class=\"greek\">ἐρχόμενον εἰς τὸν κόσμον</span>, «a verdadeira luz entrou no mundo», Jo 1:9, em que <span class=\"greek\">ἦν</span> introduz afirmação em contraste dramático com a frase inicial do versículo 8.</p>\n<p>Para indicar idade (Demétrio: 722 Fgm. 1, 2 e outros, Jacoby; POxy 275, 9 [66 d.C.]: <span class=\"greek\">οὐδέπω ὄντα τῶν ἐτῶν</span>, «ainda não tendo a idade»; Tb 14:11), Mc 5:42; Lc 3:23; At 4:22; GJs 12:3. — Mussies 304–306.</p>\n<p><strong><span class=\"greek\">γ</span>. Para expressar futuro:</strong> <span class=\"greek\">ἔσῃ σιωπῶν</span>, «ficarás calado», Lc 1:20; cf. 5:10; Mt 24:9; Mc 13:13; Lc 21:17, 24 e outros; 2Cl 17:7, Bihlmeyer, «[o menino] o servirá [a Deus]».</p>\n<p><strong>ⓒ Com particípio aoristo para expressar mais-que-perfeito</strong> (Eliano, NA 7, 11; Hippiatr. 34, 14, volume I, p. 185, 3: <span class=\"greek\">ἦν σκευάσας</span>, «havia preparado»; ISyriaW 2070b: <span class=\"greek\">ἦν κτίσας</span>, «havia fundado»; AcThom 16; 27 [Aa II/2, p. 123, 2s.; p. 142, 10]; B-D-F §355, observação; J. Vogeser, Zur Sprache der griechischen Heiligenlegenden, dissertação, Munique, 1907, 14; J. Wittmann, Sprachliche Untersuchungen zu Cosmas Indicopleustes, dissertação, Munique, 1913, 20; S. Psaltes, Grammatik der byzantinischen Chroniken, 1913, 230; Björck [fim de <span class=\"greek\">διδάσκω</span>], 75; B-D-F §355): <span class=\"greek\">ἦν βληθείς</span>, «havia sido lançado», Lc 23:19; Jo 18:30, variante. — GPt 6:23; 12:51 (cf. Justino, A II, 10, 2: <span class=\"greek\">δι</span>’ <span class=\"greek\">εὑρέσεως</span> … <span class=\"greek\">ἐστὶ πονηθέντα αὐτοῖς</span>, «alcançaram-nas mediante investigação»).</p>\n<p><strong>ⓓ Observem-se especialmente as expressões impessoais:</strong> <span class=\"greek\">δέον ἐστίν</span>, «é necessário» (Platão e outros; POxy 727, 19; prólogo de Sir, linha 3; 1Mac 12:11: <span class=\"greek\">δέον ἐστὶν καὶ πρέπον</span>, «é necessário e conveniente»), At 19:36; <span class=\"greek\">εἰ δέον ἐστίν</span>, «se for necessário», 1Pe 1:6 (veja <span class=\"greek\">δεῖ</span> 2a); 1Cl 34:2; <span class=\"greek\">πρέπον ἐστίν</span>, «convém, é apropriado» (Platão e outros; POxy 120, 24; 3Mac 7:13), Mt 3:15; 1Co 11:13.</p>\n<p><strong>ⓔ Em muitos casos, a construção com particípio destaca a duração de uma ação ou condição</strong> (BGU 183, 25: <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὸ̔ν χρόνον ζῶσα ᾖ Σαταβούς</span>, «enquanto Satabus estiver viva»; JosAs 2:1: <span class=\"greek\">ἦν</span> … <span class=\"greek\">ἐξουθενοῦσα καὶ καταπτύουσα πάντα ἄνδρα</span>, «continuava desprezando e cuspindo em todo homem»). <span class=\"greek\">ἦν διδάσκων</span>, «costumava ensinar», Mc 1:22; Lc 4:31; 19:47; <span class=\"greek\">ἦν θέλων</span>, «nutria o desejo», 23:8; <span class=\"greek\">ἦσαν νηστεύοντες</span>, «estavam praticando o jejum», Mc 2:18; <span class=\"greek\">ἦσαν συλλαλοῦντες</span>, «conversavam por algum tempo», 9:4; <span class=\"greek\">ἦν προσδεχόμενος</span>, «estava aguardando [o Reino]», 15:43; <span class=\"greek\">ἦν συγκύπτουσα</span>, «estava encurvada», Lc 13:11.</p>\n<p><strong>ⓕ Para destacar a ideia adjetiva inerente ao particípio, em vez da ação expressa pelo verbo flexionado:</strong> <span class=\"greek\">ζῶν εἰμι</span>, «estou vivo», Ap 1:18; <span class=\"greek\">ἦν ὑποτασσόμενος</span>, «era obediente», Lc 2:51; <span class=\"greek\">ἦν ἔχων κτήματα πολλά</span>, «era muito rico», Mt 19:22; Mc 10:22; <span class=\"greek\">ἴσθι ἐξουσίαν ἔχων</span>, «terás autoridade», Lc 19:17 (Luciano, Tim. 35: <span class=\"greek\">ἴσθι εὐδαιμονῶν</span>, «sê feliz»); <span class=\"greek\">ἦν καταλλάσσων</span>, «[Deus] estava reconciliando», 2Co 5:19 (cf. Melitão, P. 83, 622: <span class=\"greek\">οὗτος ἦν ὁ ἐκλεξάμενός σε</span>, «foi este quem te escolheu»; Ath. 15, 2: <span class=\"greek\">οὗτός ἐστιν ὁ</span> … <span class=\"greek\">καρπούμενος</span>, «é este quem colhe os frutos»).</p>\n<p>— L. McGaughy, Toward a Descriptive Analysis of <span class=\"greek\">ΕΙΝΑΙ</span> as a Linking Verb in the Greek New Testament, dissertação, Vanderbilt, 1970 (veja especialmente a crítica ao tratamento de <span class=\"greek\">εἰμί</span> nas edições anteriores deste léxico, pp. 12–15). — Mlt. 228. B. 635. DELG. M-M. EDNT. TW. Sv.</p></div></section></article> <article id=\"entry-eimi-go-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eîmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Homero e seguintes, em que o presente tem o significado presente de «vou».) No ático, empregado como futuro de <span class=\"greek\">ἔρχομαι</span>, «irei» (raro no grego helenístico), Jo 7:34, variante de leitura; cf. versículo 36; 12:26; 14:3; 17:24, passagens nas quais <span class=\"greek\">εἰμί</span> também pode ser lido como <span class=\"greek\">εἶμι</span> (B-D-F §99, 1). — DELG.</p></div></section></article> <article id=\"entry-heineken-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἵνεκεν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heíneken⟧</span><span class=\"separator\">·</span><span>preposição com genitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Preposição com genitivo (Píndaro e seguintes; IAsMinLyk 109; Sb 1568, 7; PGiss 40 II, 21; PGM 5, 385; LXX): <strong>por causa de, em razão de</strong>, Lc 4:18 (Is 61:1); At 28:20, variante de leitura; 2Co 3:10; veja <span class=\"greek\">ἕνεκα</span>.</p></div></section></article> <article id=\"entry-eixa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶξα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eîxa⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">εἴκω</span>.</p></div></section></article> <article id=\"entry-eipa-eipein-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶπα, εἰπεῖν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eîpa, eipeîn⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">εἶπον</span>; quanto a formas relacionadas, veja o verbete <span class=\"greek\">εἶδον</span>.</p></div></section></article> <article id=\"entry-eiper-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴπερ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eíper⟧</span><span class=\"separator\">·</span><span>conjunção; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">εἰ</span>, seção ⑥ⓛ.</p></div></section></article> <article id=\"entry-eipon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶπον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eîpon⟧</span><span class=\"separator\">·</span><span>verbo; aoristo segundo de λέγω</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>(Homero e seguintes.) Empregado como segundo aoristo de <span class=\"greek\">λέγω</span>, «dizer» (B-D-F §101, p. 46); subjuntivo <span class=\"greek\">εἴπω</span>; imperativo <span class=\"greek\">εἶπον</span>; infinitivo <span class=\"greek\">εἰπεῖν</span>; particípio <span class=\"greek\">εἰπών</span>. Às vezes recebe desinências do primeiro aoristo (Meisterhans³-Schw. 184, 6; Schweizer 182; Mayser 331; EpArist, índice): <span class=\"greek\">εἶπα</span>, <span class=\"greek\">εἶπας</span>, <span class=\"greek\">εἶπαν</span>; imperativo <span class=\"greek\">εἰπόν</span>, Mc 13:4; Lc 22:67; At 28:26 (sobre o acento, veja W-S. §6, 7d; Mlt-H. 58; por outro lado, <span class=\"greek\">εἶπον</span> segundo P. Katz, TLZ 61, 1936, 284, e B-D-F §81, 1); <span class=\"greek\">εἰπάτω</span>, <span class=\"greek\">εἴπατε</span> (GrBar 13:2), <span class=\"greek\">εἰπάτωσαν</span>; particípio <span class=\"greek\">εἴπας</span>, At 7:37; feminino <span class=\"greek\">εἴπασα</span>, Jo 11:28, variante de leitura; Hv 3, 2, 3; 4, 3, 7. Futuro <span class=\"greek\">ἐρῶ</span>; perfeito <span class=\"greek\">εἴρηκα</span>, terceira pessoa do plural <span class=\"greek\">εἰρήκασιν</span> e <span class=\"greek\">εἴρηκαν</span> (Ap 19:3), infinitivo <span class=\"greek\">εἰρηκέναι</span>; mais-que-perfeito <span class=\"greek\">εἰρήκειν</span>. Passivo: primeiro aoristo <span class=\"greek\">ἐρρέθην</span> (variante <span class=\"greek\">ἐρρήθην</span> em Rm 9:12, 26; Gl 3:16), particípio <span class=\"greek\">ῥηθείς</span>; perfeito <span class=\"greek\">εἴρηται</span>; particípio <span class=\"greek\">εἰρημένος</span> (B-D-F §§70, 1; 81, 1; 101, p. 46; W-S. §13, 13; Rob., índice). <strong>Dizer, falar.</strong></p>\n<p><strong>① Expressar pensamento, opinião ou ideia; dizer, contar.</strong></p>\n<p><strong>ⓐ Com objeto direto ou indireto, ou equivalente.</strong> <span class=\"greek\">τὸν λόγον</span>, «a palavra», Mt 26:44; <span class=\"greek\">ὅσα</span>, «quantas coisas», Lc 12:3; <span class=\"greek\">τί</span>, «o quê», versículo 11. «Contar uma parábola» (Artemidoro 4, 80: <span class=\"greek\">Μενεκράτης εἶπεν ὄνειρον</span>, «Menécrates contou um sonho»), Lc 19:11. «Dizer a verdade», 2Co 12:6 e frequentemente; <span class=\"greek\">τοῦτο ἀληθές</span>, «isto como algo verdadeiro = isto verdadeiramente», Jo 4:18. <span class=\"greek\">τί εἴπω</span>;, «que direi?», Jo 12:27. Como fórmula retórica de transição (veja também ③ abaixo), <span class=\"greek\">τί ἐροῦμεν</span>;, «que diremos ou concluiremos? Que, então?», Rm 3:5; 6:1; 7:7; 9:14, 30.</p>\n<p><span class=\"greek\">λόγον εἴς τινα</span>, «dizer alguma coisa contra alguém», Lc 12:10; também <span class=\"greek\">κατά τινος</span>, Mt 5:11; 12:32. <span class=\"greek\">τί τινι</span>, «dizer alguma coisa a alguém», Gl 3:16; <span class=\"greek\">ἔχω σοί τι εἰπεῖν</span>, «tenho algo a dizer-te» (cf. Luciano, Tim. 20), Lc 7:40; <span class=\"greek\">τί εἴπω ὑμῖν</span>;, «que vos direi?», 1Co 11:22. <span class=\"greek\">τὶ πρός τινα</span>, «dizer algo a alguém» (Platão, Prot. 345c; Herodas 2, 84; Filóstrato, Vi. Apoll. 6, 20, 6; Êx 23:13; Josefo, Vi. 205): uma parábola, Lc 12:16; «falar com referência a alguém», Mc 12:12; Lc 20:19. Também <span class=\"greek\">πρὸς ταῦτα</span>, «a respeito dessas coisas», Rm 8:31. <span class=\"greek\">τὶ περί τινος</span>, «dizer algo sobre alguém ou alguma coisa» (Xenofonte, Vect. 4, 13), Jo 7:39; 10:41; <span class=\"greek\">εἰρήκει περὶ τοῦ θανάτου</span>, «referira-se à morte», 11:13. <span class=\"greek\">ὑπὲρ</span> (variante <span class=\"greek\">περί</span>) <span class=\"greek\">οὗ ἐγὼ εἶπον</span>, «a respeito daquele de quem falei», Jo 1:30 (introduzindo fala direta). Com acusativo de pessoa: <span class=\"greek\">ὸ̔ν εἶπον</span>, «aquele de quem falei», versículo 15; cf. <span class=\"greek\">ὁ ῥηθείς</span>, «aquele que foi mencionado», Mt 3:3.</p>\n<p><span class=\"greek\">εἰπεῖν τινα καλῶς</span>, «falar bem de alguém», Lc 6:26; <span class=\"greek\">κακῶς</span>, «falar mal», At 23:5 (Êx 22:27). Com omissão do objeto mais próximo, suprido pelo contexto, Lc 22:67; Jo 9:27 e outros. Como resposta: <span class=\"greek\">σὺ εἶπας</span>, subentenda-se <span class=\"greek\">αὐτό</span>, «tu o disseste», é evasivo, ou mesmo uma negação (como o escólio a Platão 112e, em que Sócrates diz: <span class=\"greek\">σὺ ταῦτα εἶπες</span>, <span class=\"greek\">οὐκ ἐγώ</span>, «tu disseste essas coisas, não eu». Veja também a recusa de dar resposta claramente afirmativa em Const. Apost. 15, 14, 4: <span class=\"greek\">οὐκ εἶπεν ὁ κύριος</span> ‘<span class=\"greek\">ναί</span>’, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ὅτι</span> ‘<span class=\"greek\">σὺ εἶπας</span>’, «o Senhor não disse 'sim', mas 'tu o disseste'»; veja o fim de <span class=\"greek\">λέγω</span> 2e), Mt 26:25, 64.</p>\n<p>Com indicação da pessoa a quem algo é dito: em dativo, Mt 5:22; 8:10, 13, 19, 21 e frequentemente. <span class=\"greek\">τινὶ περί τινος</span>, «contar a alguém a respeito de alguma coisa», Mt 17:13; Jo 18:34. Também <span class=\"greek\">πρός τινα</span> em lugar do dativo (Luciano, Dial. Mort. 1; Josefo, Ant. 11, 210), Mc 12:7; Lc 1:13, 34, 61 e muito frequentemente (com acusativo <span class=\"greek\">εἶπον τὸν ἄγγελον</span>, GrBar 6:3; 10:7).</p>\n<p><strong>ⓑ Seguido de discurso direto:</strong> Mt 2:8; 9:22; 12:24, 49; 14:29; 15:16, 32; 17:17 e muito frequentemente. <span class=\"greek\">οὐδὲ ἐροῦσιν</span>, «nem poderão dizer», Lc 17:21 (cf. Herodas 4, 73: <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ἐρεῖς</span>, seguido de discurso direto como em Lucas). Sobre algo dito anteriormente, Jo 14:28. — Como fórmula que introduz objeção (Diodoro Sículo 13, 21, 5: <span class=\"greek\">ἐροῦσί τινες ἴσως</span>, «talvez alguns dirão»; Díon Crisóstomo 14 [31], 47: <span class=\"greek\">ἴσως οὖν ἐρεῖ τις</span>, «talvez, pois, alguém dirá»): <span class=\"greek\">ἀλλὰ ἐρεῖ τις</span>, «mas alguém dirá» (Xenofonte, Cyr. 4, 3, 10; Apiano, Bell. Civ. 3, 16 §59: <span class=\"greek\">ἀλλὰ</span> … <span class=\"greek\">ἐρεῖ τις</span>; Pseudo-Clemente, Hom. 9, 16, p. 98, 1; 5 Lag.), 1Co 15:35; Tg 2:18 (sobre as diversas interpretações, D. Verseput, NTS 43, 1997, 108, nota 22). <span class=\"greek\">ἐρεῖς οὖν</span>, «dirás então», Rm 11:19; com <span class=\"greek\">μοι</span>, «a mim», em 9:19. <span class=\"greek\">πρὸς ἡμᾶς</span>, «a nós», At 21:13, códice D. Intercalado: <span class=\"greek\">τίς οὖν αὐτῶν</span>, <span class=\"greek\">εἰπέ</span>, <span class=\"greek\">πλεῖον ἀγαπήσει αὐτόν</span>;, «qual deles, dize-me, o amará mais?», Lc 7:42, variante.</p>\n<p><strong>ⓒ Seguido de <span class=\"greek\">ὅτι</span>:</strong> (Diodoro Sículo 12, 16, 5; 12, 74, 3; Josefo, Vi. 205) Mt 28:7, 13; Jo 7:42; 8:55; 16:15; 1Jo 1:6, 8, 10; 1Co 1:15; 14:23 e outros.</p>\n<p><strong>ⓓ Seguido de acusativo e infinitivo:</strong> Rm 4:1 (texto incerto).</p>\n<p><strong>ⓔ Regularmente usado em citações:</strong> Tt 1:12; geralmente do Antigo Testamento: <span class=\"greek\">ἐρρέθη</span>, «foi dito», Rm 9:12; <span class=\"greek\">καθὼς εἴρηκεν</span>, «conforme disse», Hb 4:3. <span class=\"greek\">τὸ ῥηθὲν ὑπὸ κυρίου διὰ τοῦ προφήτου</span>, «o que foi dito pelo Senhor por intermédio do profeta», Mt 1:22; <span class=\"greek\">ὑπὸ τ</span>. <span class=\"greek\">θεοῦ</span>, «por Deus», Mt 22:31; <span class=\"greek\">διὰ τοῦ προφήτου</span>, «pelo profeta», At 2:16; cf. Mt 2:17, 23; 4:14; 8:17; 12:17; 13:35; 24:15 (Justino, D. 27, 1: <span class=\"greek\">διὰ</span> … <span class=\"greek\">Ἠσαίου οὕτως εἴρηται</span>, «foi dito assim por Isaías») e outros. <span class=\"greek\">τὸ εἰρημένον</span>, «o que está escrito», Lc 2:24; At 13:40; Rm 4:18. — E. Howind, De ratione citandi in Ciceronis Plutarchi Senecae Novi Testamenti scriptis obvia, dissertação, Marburgo, 1921.</p>\n<p><strong>ⓕ Com perguntas seguidas de discurso direto</strong> (Epicteto 3, 23, 18a = «perguntar»; Zc 1:9a), Mt 9:4; 17:19, 24; 18:21; 20:32; 26:15 e outros; com dativo de pessoa, Mt 13:10, 27.</p>\n<p><strong>ⓖ Com modificador adverbial:</strong> <span class=\"greek\">ὁμοίως</span>, «semelhantemente», Mt 26:35; <span class=\"greek\">ὡσαύτως</span>, «da mesma maneira», 21:30; ou expressão adverbial: <span class=\"greek\">ἐν παραβολαῖς</span>, «em parábolas» = «parabolicamente», 22:1; <span class=\"greek\">διὰ παραβολῆς</span>, «por meio de parábola», Lc 8:4. Com <span class=\"greek\">καθώς</span>, referente a algo dito anteriormente (Josefo, Ant. 8, 273: <span class=\"greek\">καθὼς εἶπεν ὁ προφήτης</span>, «como disse o profeta»; cf. Dt 1:21; 19:8; Is 41:22: <span class=\"greek\">τὰ ἐπερχόμενα εἴπατε ἡμῖν</span>, «anunciai-nos as coisas que vêm»), Mt 28:6; Mc 14:16; Lc 22:13; cf. Jo 16:4. <span class=\"greek\">εἰπὲ λόγῳ</span>, «dize uma palavra», Lc 7:7; Mt 8:8. <span class=\"greek\">διὰ φωνῆς πνεύματος ἁγίου</span>, «pela voz do Espírito Santo», AcPl Ha 11, 5.</p>\n<p><strong>② Responder a uma pergunta; responder, replicar.</strong> (Pseudo-Platão, De Virt. 2, 376d: <span class=\"greek\">οὐκ ἔχω εἰπεῖν</span>, «não consigo responder»; Pseudo-Platão, Eryx. 21, p. 401D: <span class=\"greek\">ἔχειν εἰπεῖν</span>, «ser capaz de responder».) Mt 15:34; 16:14; 26:18 e outros. Sobre o emprego juntamente com <span class=\"greek\">ἀποκρίνεσθαι</span>, frequente em narrativas para indicar transição, veja <span class=\"greek\">ἀποκρίνεσθαι</span> ②. Também, em conversação, sem pergunta precedente, Mt 14:18; 15:27; Mc 9:39; Lc 1:38 e frequentemente.</p>\n<p><strong>③ Chegar a uma conclusão mediante raciocínio; concluir.</strong> Na fórmula de transição <span class=\"greek\">τί ἐροῦμεν</span>;, «que conclusão devemos tirar?», Rm 3:5; 6:1; 9:14, 30; quanto a Rm 4:1, veja F. Danker, em Gingrich Festschrift, 1972, 103s. Veja também ①ⓐ.</p>\n<p><strong>④ Aplicar nome ou designação a alguém; chamar.</strong> Com duplo acusativo (Máximo de Tiro 14, 5c: <span class=\"greek\">κόλακα τὸν Ὀδυσσέα</span>, «[chamar] Ulisses de adulador»; Diógenes Laércio 6, 40: Diógenes, o Cínico, é chamado «cão»; SibOr 4, 140): <span class=\"greek\">ἐκείνους εἶπεν θεούς</span>, «chamou aqueles de deuses», Jo 10:35; <span class=\"greek\">ὑμᾶς εἴρηκα φίλους</span>, «vos chamei amigos», 15:15 (cf. Od. 19, 334; Xenofonte, Apol. 15; Luciano, Tim. 20).</p>\n<p><strong>⑤ Dar instruções ou ordens; dizer, ordenar.</strong> (Êx 19:8b; 2Cr 24:8; seguido de infinitivo: Êx 35:1b; Sb 9:8; Epicteto 1, 14, 3: <span class=\"greek\">ὅταν</span> [<span class=\"greek\">ὁ θεὸς</span>] <span class=\"greek\">εἴπῃ τοῖς φυτοῖς ἀνθεῖν</span>, <span class=\"greek\">ἀνθεῖ</span>, «quando [Deus] diz às plantas que floresçam, elas florescem»; inscrição de Abércio, linha 17.) <span class=\"greek\">εἶπεν δοθῆναι αὐτῇ φαγεῖν</span>, «ordenou que lhe dessem algo para comer», Mc 5:43; <span class=\"greek\">εἶπεν καὶ ταῦτα παρατιθέναι</span>, «mandou pôr também essas coisas diante [do povo]», 8:7. Seguido de <span class=\"greek\">ἵνα</span>, Mt 4:3; Mc 9:18; Lc 4:3.</p>\n<p><strong>⑥ Dizer alguma coisa a si mesmo; pensar.</strong> Correspondendo ao hebraico <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">אָמַר</bdi> <bdi class=\"hebrew\" lang=\"he\" dir=\"rtl\">בְּלִבּוֹ</bdi>, a expressão <span class=\"greek\">εἰπεῖν ἐν ἑαυτῷ</span> (Est 6:6; Tb 4:2 BA; manuscrito S: <span class=\"greek\">ἐν τῇ καρδίᾳ αὐτοῦ</span>) significa «dizer a si mesmo, em silêncio, pensar consigo», Mt 9:3; Lc 7:39; 16:3; 18:4; também <span class=\"greek\">ἐν τῃ καρδίᾳ αὐτοῦ</span>, «em seu coração» (Dt 8:17; 9:4; Sl 9:27; 13:1; veja acima), Lc 12:45; Rm 10:6.</p>\n<p>Nos manuscritos e edições, <span class=\"greek\">εἶπον</span> frequentemente alterna com <span class=\"greek\">λαλέω</span>, <span class=\"greek\">λέγω</span> e <span class=\"greek\">φημί</span> e aparece como variante de leitura em Mt 19:18; Mc 6:16; Lc 19:30; Jo 7:45, 50; 9:10; 13:24; At 23:7. — B. 1253s. DELG, s.v. <span class=\"greek\">ἔπος</span> 2; Frisk, s.v. <span class=\"greek\">εἶπον</span> e <span class=\"greek\">ἔπος</span>. M-M. TW. Veja também <span class=\"greek\">λέγω</span>.</p></div></section></article> <article id=\"entry-eipos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴπως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eípōs⟧</span><span class=\"separator\">·</span><span>conjunção; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><p>Veja <span class=\"greek\">εἰ</span>, seção ⑥ⓝ.</p></div></section></article>"};
